// Üretilen dosya: tool/ozgun/uret.py. Matematik · Fonksiyonlar ve grafik yorumu (metinle) (orta).
const ozMathematics7Orta = <(String, String, List<String>, String)>[
  ('Her doğal sayıyı, kendisini tam bölen asal sayıya eşleyen kural neden fonksiyon belirtmez?', 'Bazı sayıların birden çok asal böleni vardır', ['Asal sayıların sayısı sonsuz olduğundan eşleme bitmez', 'Bazı asal sayılar hiçbir sayıyı bölmez', 'Çift sayılar tek bir asala gider'], 'Örneğin 6 sayısı hem 2\'ye hem 3\'e eşlenir; bir girdinin iki çıktısı olduğundan kural fonksiyon değildir. Ayrıca 1\'in hiç asal böleni yoktur.'),
  ('Bir öğrenci, düşey doğru testini geçen her eğrinin yatay doğru testini de geçeceğini söylüyor. Hangi örnek bu iddiayı çürütür?', 'y = x² parabolü', ['y = 2x + 1 doğrusu', 'y = x³ eğrisi', 'y = √x eğrisi'], 'y = x² bir fonksiyonun grafiğidir, ancak y = 4 yatay doğrusu onu iki noktada keser. Diğer seçeneklerdeki eğriler her iki testi de geçer.'),
  ('Bir dikdörtgenler prizmasının hacmi kenar uzunluğu x cm olan kare taban ve 10 cm yükseklik için V(x) = 10x² cm³ ile verilir. Taban kenarı iki katına çıkarılırsa hacim kaç katına çıkar?', '4', ['2', '8', '20'], 'V(2x) = 10·(2x)² = 40x² = 4·V(x). Hacim, kenarın karesiyle orantılı olduğundan 4 katına çıkar.'),
  ('Bir telefonun şarjı t saat kullanımdan sonra Ş(t) = 100 − 12,5t yüzdesiyle modelleniyor. Bu modelin anlamlı olduğu t aralığı hangisidir?', '[0, 8]', ['[0, 12,5]', '[0, 100]', '[8, 12,5]'], 'Şarj 0 ile 100 arasında olmalıdır. 100 − 12,5t = 0 eşitliği t = 8 verir; bu yüzden model 0 ≤ t ≤ 8 aralığında anlamlıdır.'),
  ('Bir arabanın yakıt tüketimi, hızı v km/sa olmak üzere 100 km\'de Y(v) = 0,002v² − 0,2v + 10 litre olarak modelleniyor. Araç saatte 100 km hızla giderken 100 km\'de kaç litre yakıt harcar?', '10', ['10,5', '12', '14'], 'Y(100) = 0,002·10 000 − 0,2·100 + 10 = 20 − 20 + 10 = 10 litredir.'),
  ('f(x) = √(x − 2) + 1/(x − 5) fonksiyonunun gerçek sayılardaki en geniş tanım kümesi hangisidir?', '[2, ∞) − {5}', ['(2, ∞) − {5}', '[2, 5)', 'ℝ − {2, 5}'], 'Kök içi için x ≥ 2, payda için x ≠ 5 gerekir. İki koşulun kesişimi [2, ∞) − {5} kümesidir.'),
  ('Paydasında karekök bulunan 1/√(4 − x) ifadesi hangi x değerleri için gerçek bir sayı belirtir?', '(−∞, 4)', ['(−∞, 4) ∪', '(4, ∞)', '[4, ∞)'], 'Kök içi pozitif olmalıdır; sıfır olursa payda sıfırlanır. 4 − x > 0, yani x < 4 bulunur.'),
  ('f(x) = √(x + 3) · √(1 − x) fonksiyonunun en geniş tanım kümesindeki tam sayıların toplamı kaçtır?', '−5', ['−6', '−10', '−3'], 'x + 3 ≥ 0 ve 1 − x ≥ 0 koşulları x ∈ [−3, 1] verir. Tam sayılar −3, −2, −1, 0, 1 olup toplamları −5\'tir.'),
  ('Payı ∛(x − 7), paydası x + 2 olan kesirli fonksiyonun tanımsız kaldığı yerleri dışlarsak geriye hangi küme kalır?', 'ℝ − {−2}', ['[7, ∞)', '[7, ∞) − {−2}', 'ℝ − {−2, 7}'], 'Küpkök her gerçek sayı için tanımlıdır, bu yüzden pay hiçbir kısıt getirmez. Yalnız payda sıfır olamaz: x ≠ −2.'),
  ('5/(x² + 2x + 1) kuralının sayı doğrusu üzerinde anlam taşımadığı noktalar atıldığında elde edilen küme hangisidir?', 'ℝ − {−1}', ['ℝ', 'ℝ − {1}', 'ℝ − {−1, 1}'], 'Payda (x + 1)² biçimindedir ve yalnız x = −1 için sıfır olur. Bu nokta dışında fonksiyon her yerde tanımlıdır.'),
  ('Mutlak değer fonksiyonu yalnız −3 ile 2 arasındaki (uçlar dahil) girdiler için kullanılırsa çıktılar hangi aralığı doldurur?', '[0, 3]', ['[2, 3]', '[0, 2]', '[−3, 2]'], 'Aralık 0\'ı içerdiği için en küçük değer f(0) = 0\'dır. En büyük değer uç noktalardan |−3| = 3\'tür.'),
  ('6/x kuralı yalnız 1 ≤ x ≤ 3 için çalıştırılırsa elde edilen çıktıların kümesi hangisidir?', '[2, 6]', ['[1, 6]', '[2, 3]', '[3, 6]'], 'x > 0\'da 6/x azalandır. f(1) = 6 ve f(3) = 2 olduğundan görüntü kümesi [2, 6] olur.'),
  ('Üstel 2ˣ fonksiyonuna −1\'den 3\'e kadar olan girdiler verildiğinde alınan değerlerin aralığı nedir?', '[1/2, 8]', ['[−2, 8]', '[0, 8]', '[1/2, 6]'], '2ˣ artan bir fonksiyondur. f(−1) = 1/2 en küçük, f(3) = 8 en büyük değerdir.'),
  ('A = {−1, 0, 1} kümesinde tanımlı f(x) = x³ ve g(x) = x kuralları karşılaştırıldığında hangi sonuca varılır?', 'Bu küme üzerinde f ve g eşit fonksiyonlardır', ['Kuralları farklı olduğu için hiçbir kümede eşit olamazlar', 'Yalnız x = 0\'da aynı değeri alırlar', 'f\'nin görüntü kümesi g\'ninkinden geniştir'], 'Eşitlik için aynı tanım kümesinde her elemanın görüntüsü aynı olmalıdır. (−1)³ = −1, 0³ = 0, 1³ = 1 olduğundan bu küme üzerinde f = g\'dir.'),
  ('Gerçek sayılarda f(x) = √(x²) ile g(x) = (√x)² kuralları neden aynı fonksiyonu belirtmez?', 'f her gerçek x\'te tanımlı, g ise yalnız x ≥ 0\'da tanımlıdır', ['f negatif değer alabilir ama g hiçbir zaman alamaz', 'İkisinin de tanım kümesi [0, ∞) ama değerleri farklıdır', 'g her x için |x| değerini verir'], '√(x²) = |x| olup her x için tanımlıdır. (√x)² ise x ≥ 0 olmadıkça tanımsızdır; tanım kümeleri farklı olduğundan fonksiyonlar eşit değildir.'),
  ('f(x) = (a − 1)x + 5 ve g(x) = 3x + b − 2 fonksiyonları gerçek sayılarda eşit olduğuna göre a + b kaçtır?', '11', ['10,5', '7', '12'], 'Katsayılar eşleştirilir: a − 1 = 3 ise a = 4; b − 2 = 5 ise b = 7. Toplam 11\'dir.'),
  ('Bir mumun boyu yakıldıktan 2 saat sonra 16 cm, 5 saat sonra 10 cm ölçülüyor. Boy zamanla doğrusal azaldığına göre mumun ilk boyu kaç cm\'dir?', '20', ['18,5', '22', '24'], 'Saatlik değişim (10 − 16)/(5 − 2) = −2 cm\'dir. Başlangıç boyu 16 + 2·2 = 20 cm olur.'),
  ('Bir spor salonu üyelik için tek seferlik 300 TL kayıt ücreti ve ayda 250 TL aidat alıyor. Toplam ödemenin ilk kez 2000 TL\'yi aştığı ay sayısı kaçtır?', '7', ['6', '8', '5'], '300 + 250n > 2000 için 250n > 1700, n > 6,8 olur. En küçük tam sayı 7\'dir; 6 ayda toplam 1800 TL, 7 ayda 2050 TL\'dir.'),
  ('Bir matbaa davetiye siparişinde kalıp hazırlığı için sabit bir ücret ve her davetiye için aynı tutarı alıyor. 100 davetiye 450 TL, 250 davetiye 900 TL tuttuğuna göre kalıp ücreti kaç TL\'dir?', '150', ['100', '200', '112,5'], 'Davetiye başı ücret (900 − 450)/150 = 3 TL\'dir. Kalıp ücreti 450 − 100·3 = 150 TL olur.'),
  ('Bir şehrin nüfusu yıllara göre doğrusal bir modelle N(t) = 85 000 + 1 200t ile tahmin ediliyor (t: 2000\'den bu yana geçen yıl). Bu modele göre 1 200 sayısının anlamı nedir?', 'Nüfusun her yıl yaklaşık 1 200 kişi artmasıdır', ['2000 yılındaki nüfusun 1 200 olmasıdır', 'Nüfusun 1 200 yıl içinde iki katına çıkacağının tahmin edilmesidir', 'Nüfusun her yıl yüzde 1,2 oranında artmasıdır'], 'Eğim, girdi bir birim arttığında çıktının ne kadar değiştiğini gösterir. Burada her yıl sabit 1 200 kişilik artış vardır; bu bir oran değil sabit miktardır.'),
  ('Bir doğrusal fonksiyonun eğiminin 0 olması, bu fonksiyonla modellenen bir durum için ne anlama gelir?', 'Girdi değişse de çıktı hep aynı kalır', ['Çıktı girdiyle tam olarak aynı hızda artar', 'Çıktı her zaman sıfırdır', 'Girdi ile çıktı ters orantılıdır'], 'Eğim 0 ise f(x) = b biçiminde sabit fonksiyon elde edilir. Girdi ne olursa olsun çıktı b\'ye eşit kalır; çıktının sıfır olması gerekmez.'),
  ('A kargo firması gönderi başına 30 TL artı kilogram başına 6 TL, B firması 18 TL artı kilogram başına 10 TL alıyor. Kaç kilogramlık gönderide iki firma aynı ücreti ister?', '3', ['2', '4', '6'], '30 + 6k = 18 + 10k eşitliğinden 12 = 4k, k = 3 bulunur. Bu ağırlıkta ikisi de 48 TL ister.'),
  ('İki mobil paketten birincisi ayda 120 TL sabit, ikincisi 40 TL artı her GB için 16 TL\'dir. Ayda en az kaç tam GB kullanan bir kişi için sabit paket daha ucuzdur?', '6', ['5', '4', '8'], '40 + 16g > 120 için g > 5 olmalıdır. 5 GB\'ta iki paket eşit (120 TL) olduğundan sabit paket 6 GB ve üzerinde daha ucuzdur.'),
  ('f(x) = (m + 3)x² + (n − 1)x + 4 fonksiyonu sabit bir fonksiyon olduğuna göre m·n çarpımı kaçtır?', '−3', ['3', '−4', '4'], 'Sabit olması için x\'li terimlerin katsayıları sıfır olmalıdır: m = −3 ve n = 1. Çarpım −3\'tür.'),
  ('f(x) = (2a − 4)x + b + 3 fonksiyonu gerçek sayılarda birim (özdeşlik) fonksiyonu olduğuna göre a + b kaçtır?', '−0,5', ['0,5', '−1', '−1,25'], 'Birim fonksiyon f(x) = x\'tir. 2a − 4 = 1 ise a = 2,5; b + 3 = 0 ise b = −3. Toplam −0,5\'tir.'),
  ('Bir dağcı yüksekliği her 100 m arttığında havanın yaklaşık 0,65 °C soğuduğunu öğreniyor. Deniz seviyesinde 20 °C iken 2 000 m yükseklikteki sıcaklık bu doğrusal modele göre kaç °C\'dir?', '7', ['13', '6,5', '8'], '2 000 m, 20 tane 100 m demektir; düşüş 20·0,65 = 13 °C olur. Sıcaklık 20 − 13 = 7 °C\'dir.'),
  ('g fonksiyonu negatif girdiler için −2x, sıfır ve pozitif girdiler için x + 4 değerini veriyor. g(a) = 6 eşitliğini sağlayan a değerlerinin toplamı kaçtır?', '−1', ['2', '−3', '5'], 'Negatif bölgede −2a = 6 ise a = −3. Diğer bölgede a + 4 = 6 ise a = 2. Toplam −1\'dir.'),
  ('h fonksiyonu x < 1 iken 3x + k, x ≥ 1 iken x² + 4 kuralına uyuyor. Grafiğin x = 1\'de kopmadan birleşmesi için k kaç olmalıdır?', '2', ['1', '5', '4'], 'Sol parça x = 1\'de 3 + k, sağ parça 5 değerine ulaşır. 3 + k = 5 için k = 2 olmalıdır.'),
  ('p fonksiyonu tek sayılar için n + 1, çift sayılar için n/2 sonucunu veren bir tam sayı fonksiyonudur. p(p(p(7))) kaçtır?', '2', ['4', '1', '8'], 'p(7) = 8, p(8) = 4, p(4) = 2. Sonuç 2\'dir.'),
  ('Bir kargo firması 2 kg\'a kadar paketlere 50 TL, 2 kg\'ı aşan her kilogram (ya da kesri) için ayrıca 12 TL alıyor. 4,3 kg\'lık paket için ücret kaç TL\'dir?', '86', ['77,6', '74', '98'], '2 kg\'ı aşan kısım 2,3 kg\'dır; kesir tam kilogram sayıldığından 3 kg ücretlendirilir. Ücret 50 + 3·12 = 86 TL\'dir.'),
  ('Bir elektrik tarifesinde ilk 150 kWh için kWh başına 2 TL, 150 kWh\'yi aşan kısım için kWh başına 3 TL alınıyor. Faturası 600 TL olan bir abone kaç kWh harcamıştır?', '250', ['200', '300', '225'], 'İlk 150 kWh 300 TL tutar. Kalan 300 TL, 3 TL\'lik dilimde 100 kWh\'ye karşılık gelir. Toplam 250 kWh\'dir.'),
  ('Bir okul gezisine 137 öğrenci katılacak ve her otobüs 40 kişi alıyor. Gereken otobüs sayısını veren işlemin sonucu kaçtır?', '4', ['3', '5', '3,4'], 'Gereken sayı ⌈137/40⌉ = ⌈3,425⌉ = 4\'tür; 3 otobüs yalnız 120 kişi taşır.'),
  ('Bir yüzme havuzunda 12 yaş altı çocuklar 40 TL, 12–64 yaş arası (uçlar dahil) 80 TL, 65 yaş ve üstü 50 TL ödüyor. 11, 12, 64 ve 65 yaşlarındaki dört kişi toplam kaç TL öder?', '250', ['240', '260', '290'], '11 yaş: 40, 12 yaş: 80, 64 yaş: 80, 65 yaş: 50 TL. Toplam 250 TL\'dir; sınır yaşlarına dikkat edilmelidir.'),
  ('Bir taksimetre ilk 2 km için 60 TL gösteriyor, sonrasında her km için 25 TL ekliyor. Ücret fonksiyonunun x > 2 için kuralı hangisidir?', '10 + 25x', ['60 + 25x', '25x', '60 + 25(x + 2)'], 'x > 2 için ücret 60 + 25(x − 2) = 25x + 10\'dur.'),
  ('y = |x − 4| grafiği ile x ekseni ve y ekseni arasında kalan üçgensel bölgenin alanı kaç birimkaredir?', '8', ['16', '4', '12,5'], 'Grafik y eksenini (0, 4)\'te, x eksenini (4, 0)\'da keser. Dik kenarları 4 olan üçgenin alanı 4·4/2 = 8\'dir.'),
  ('y = f(x) grafiği (−1, 4) noktasından geçiyor. y = f(x) + 7 grafiği hangi noktadan kesinlikle geçer?', '(−1, 11)', ['(6, 4)', '(−8, 4)', '(−1, −3)'], 'Düşey ötelemede apsis aynı kalır, ordinata 7 eklenir: (−1, 4 + 7) = (−1, 11).'),
  ('y = f(x) fonksiyonunun sıfırları −3 ve 2\'dir. y = f(x + 4) fonksiyonunun sıfırlarının toplamı kaçtır?', '−9', ['−1', '7', '−5'], 'Grafik 4 birim sola kayar; sıfırlar −7 ve −2 olur. Toplam −9\'dur.'),
  ('Tanım kümesi [0, 6] olan f fonksiyonu için y = f(x − 2) fonksiyonunun tanım kümesi hangisidir?', '[2, 8]', ['[−2, 4]', '[0, 6]', '[2, 6]'], 'f(x − 2) tanımlı olması için 0 ≤ x − 2 ≤ 6 gerekir; bu 2 ≤ x ≤ 8 verir.'),
  ('y = √x grafiği 2 birim sola ve 1 birim aşağı ötelenirse hangi fonksiyonun grafiği elde edilir?', 'y = √(x + 2) − 1', ['y = √(x − 2) − 1', 'y = √(x + 2) + 1', 'y = √(x − 1) + 2'], 'Sola öteleme x yerine x + 2 yazmakla, aşağı öteleme fonksiyondan 1 çıkarmakla yapılır.'),
  ('y = f(x) grafiğinin üzerindeki (3, −2) noktası y eksenine göre yansıtılırsa yeni grafik hangi fonksiyona aittir ve nokta nereye gider?', 'y = f(−x); (−3, −2)', ['y = −f(x); (3, 2)', 'y = −f(−x); (−3, 2)', 'y = f(−x); (3, 2)'], 'y eksenine göre yansımada apsisin işareti değişir, ordinat aynı kalır. Bu dönüşüm kuralda x yerine −x yazmaya karşılık gelir.'),
  ('f(x) = 2ˣ grafiği x eksenine göre yansıtılırsa yeni grafiğin görüntü kümesi hangisi olur?', '(−∞, 0)', ['(0, ∞)', '(−∞, 0]', '(−∞, −1)'], 'Yansımadan sonra y = −2ˣ elde edilir. 2ˣ her zaman pozitif olduğundan −2ˣ her zaman negatiftir ve 0\'a ulaşmaz.'),
  ('(6, 3) noktası f\'nin eğrisi üzerindedir. Girdinin üçte birinin f\'ye verildiği y = f(x/3) eğrisi üzerinde kesinlikle yer alan nokta hangisidir?', '(18, 3)', ['(2, 3)', '(6, 1)', '(18, 9)'], 'f(x/3) = 3 olması için x/3 = 6, yani x = 18 olmalıdır. Grafik yatayda 3 kat genişler.'),
  ('f\'nin girdileri −4 ile 8 arasında (uçlar dahil) olabiliyorsa, f(2x) ifadesinin anlamlı olduğu x\'ler hangi aralığı oluşturur?', '[−2, 4]', ['[−8, 16]', '[−4, 8]', '[−8, 4]'], '−4 ≤ 2x ≤ 8 koşulundan −2 ≤ x ≤ 4 bulunur. Yatay daraltma tanım kümesini de yarıya indirir.'),
  ('Görüntü kümesi [−2, 6] olan bir f için y = (1/2)·f(x) kuralının alabileceği değerler hangi aralıktadır?', '[−1, 3]', ['[−4, 12]', '[−2, 6]', '[−1, 6]'], 'Her çıktı yarıya iner: −2 → −1 ve 6 → 3. Düşey daraltma görüntü kümesini aynı oranda küçültür.'),
  ('y = f(x) grafiği düşey doğrultuda 2 kat uzatılırsa x eksenini kestiği noktalar için ne söylenebilir?', 'Değişmeden kalırlar', ['Apsisleri iki katına çıkar', 'Apsisleri yarıya iner', 'Tamamı y eksenine kayar'], 'Düşey uzatmada ordinatlar 2 ile çarpılır; ordinatı 0 olan noktalar 0\'da kalır. Bu yüzden x ekseni kesişimleri korunur.'),
  ('(4, 2) noktası y = f(x) grafiği üzerindedir. y = 3f(x − 1) + 2 grafiği üzerinde kesinlikle bulunan nokta hangisidir?', '(5, 8)', ['(3, 8)', '(5, 12)', '(5, 9)'], 'x − 1 = 4 için x = 5 olur; f(4) = 2 olduğundan y = 3·2 + 2 = 8\'dir.'),
  ('y = f(x) grafiğinden y = f(−x + 2) grafiği elde edilirken hangi sıra doğru sonuç verir?', 'Önce 2 birim sola ötele, sonra y eksenine göre yansıt', ['Önce y eksenine göre yansıt, sonra 2 birim sola ötele', 'Önce 2 birim sağa ötele, sonra x eksenine göre yansıt', 'Önce x eksenine göre yansıt, sonra 2 birim yukarı kaydır'], 'f(x + 2) grafiği sola ötelemedir; ardından x yerine −x yazmak f(−x + 2) verir. Diğer sırada yansıma ve sağa öteleme gerekirdi.'),
  ('Tepe noktası (1, 3) olan V biçimli bir grafik 2 birim sola ve 5 birim aşağı ötelenirse yeni tepe noktası neresi olur?', '(−1, −2)', ['(3, −2)', '(−1, 8)', '(3, 8)'], 'Sola öteleme apsisten 2, aşağı öteleme ordinattan 5 çıkarır: (1 − 2, 3 − 5) = (−1, −2).'),
  ('f(x) = x³ grafiğine hangi dönüşüm dizisi uygulanırsa g(x) = −(x − 2)³ + 1 grafiği elde edilir?', 'x eksenine göre yansıtma, 2 sağa ve 1 yukarı öteleme', ['y eksenine göre yansıtma, 2 sola ve 1 yukarı öteleme', 'x eksenine göre yansıtma, 2 sola ve 1 aşağı öteleme', 'Orijine göre yansıtma ve ardından yalnızca 1 birim sağa öteleme'], 'Başındaki eksi x eksenine göre yansımadır; x − 2 sağa 2, +1 yukarı 1 birim ötelemedir.'),
  ('y = |x² − 4| grafiğinin x eksenini kestiği ya da ona değdiği noktaların sayısı kaçtır?', '2', ['4', '1', 'Hiç yoktur, eksenin üstündedir'], 'Mutlak değer yalnız işaret değiştirir, sıfırları değiştirmez. x² − 4 = 0 eşitliği x = ±2\'de sağlanır.'),
  ('Bir çift fonksiyonun grafiği (−2, 7) noktasından geçiyorsa aşağıdaki noktalardan hangisinden de kesinlikle geçer?', '(2, 7)', ['(2, −7)', '(−2, −7)', '(7, −2)'], 'Çift fonksiyonda f(−x) = f(x)\'tir; grafik y eksenine göre simetriktir. Bu yüzden (2, 7) de grafiktedir.'),
  ('f(x) = x² + (k − 3)x + 1 fonksiyonunun grafiği y eksenine göre simetrik olduğuna göre k kaçtır?', '3', ['−3', '0', '1'], 'y eksenine göre simetri çift fonksiyon demektir; tek dereceli terim kalmamalıdır. k − 3 = 0 ise k = 3\'tür.'),
  ('Gerçek sayılarda tanımlı çift bir f fonksiyonu için f(4) − f(−4) + f(0) ifadesi her zaman neye eşittir?', 'f(0)', ['2f(4)', '0', 'f(4)'], 'Çift fonksiyonda f(−4) = f(4) olduğundan ilk iki terim birbirini götürür; geriye f(0) kalır.'),
  ('Her gerçek sayı için tanımlı tek bir f fonksiyonu ile ilgili f(2) + f(−2) + f(0) + f(5) = 9 bilgisi veriliyor. f(−5) kaçtır?', '−9', ['9', '0', '−4,5'], 'Tek fonksiyonda f(−2) = −f(2) ve f(0) = 0\'dır. Bu yüzden f(5) = 9 olur ve f(−5) = −9\'dur.'),
  ('y = f(x) grafiğindeki en yüksek nokta (2, 10) ise y = f(2x) grafiğindeki en yüksek nokta hangisidir?', '(1, 10)', ['(4, 10)', '(2, 20)', '(1, 20) noktası'], 'Yatay daraltmada apsis yarıya iner, ordinat aynı kalır. En büyük değer 10\'dur ve x = 1\'de alınır.'),
  ('[−4, 5] aralığında tanımlı f\'nin grafiği (−4, 0) noktasından (−1, 3) noktasına doğrusal yükseliyor, sonra (2, −3) noktasına doğrusal iniyor, ardından (5, 1) noktasına doğrusal çıkıyor. f hangi aralıkta azalandır?', '[−1, 2]', ['[−4, −1]', '[2, 5]', '[−1, 2] ∪ [2, 5]'], 'Grafik yalnız (−1, 3) ile (2, −3) arasında aşağı iniyor. Diğer iki parçada değerler artıyor.'),
  ('Bir fonksiyonun grafiği (0, 2)\'den başlayıp (3, 8)\'e yükselen, (6, 1)\'e alçalan ve (9, 5)\'e yeniden yükselen üç doğru parçasından oluşuyor. Fonksiyonun bu aralıktaki en küçük değeri kaçtır?', '1', ['2', '0', '1,5'], 'Uç ve dönüm noktalarının ordinatları 2, 8, 1 ve 5\'tir. Bunların en küçüğü 1\'dir ve x = 6\'da alınır.'),
  ('[0, 8] aralığında tanımlı g\'nin grafiği (0, 1)\'den (2, 5)\'e, oradan (5, 0)\'a, oradan da (8, 4)\'e uzanan doğru parçalarıdır. g(x) = 3 denkleminin kaç çözümü vardır?', '3', ['2', '1', 'Sonsuz sayıda'], 'y = 3 doğrusu yükselen ilk parçayı, inen ikinci parçayı ve yükselen üçüncü parçayı birer kez keser. Toplam 3 çözüm vardır.'),
  ('Bir f fonksiyonu (−∞, 1) aralığında pozitif, (1, ∞) aralığında negatif değerler alıyor ve f(1) = 0\'dır. f(x) ≥ 0 eşitsizliğinin çözüm kümesi nedir?', '(−∞, 1]', ['(−∞, 1)', '[1, ∞)', '(1, ∞) ∪ {0}'], 'Pozitif olduğu yerler (−∞, 1), sıfır olduğu yer x = 1\'dir. Birleşim (−∞, 1] olur.'),
  ('Bir fırının sıcaklığı açıldıktan sonra 15 dakika boyunca hızla artıyor, sonra 40 dakika sabit kalıyor, kapatılınca yavaşça düşüyor. Sıcaklık-zaman grafiğinin ortasındaki bölüm nasıl görünür?', 'Yatay bir doğru parçası', ['Yükselen bir doğru parçası', 'Aşağı inen bir eğri', 'Düşey bir doğru parçası'], 'Sıcaklığın değişmediği bölümde çıktı sabit kalır; bu, zaman eksenine paralel yatay bir çizgi olarak görünür.'),
  ('Bir öğrenci evden okula giderken önce yürüyor, sonra bir süre durakta otobüs bekliyor, sonra otobüsle okula hızla ulaşıyor. Evden uzaklık-zaman grafiğinde en dik bölüm hangi aşamaya aittir?', 'Otobüsle yolculuk', ['Yürüme', 'Durakta bekleme', 'Okula varış sonrası'], 'Eğim birim zamanda alınan yoldur. En hızlı hareket otobüsle olduğundan bu aşama en dik bölümdür; bekleme yatay bir parçadır.'),
  ('Gün boyunca bir şehrin sıcaklığı sabah 06.00\'da 8 °C ile en düşük değerinde, öğleden sonra 15.00\'te 22 °C ile en yüksek değerindedir. Bu bilgiye göre 06.00–15.00 arasında sıcaklık fonksiyonu için hangi çıkarım en uygundur?', 'Bu aralıkta genel olarak yükselen bir eğilim gösterir', ['Bu aralıkta sabit kalmıştır', 'Bu aralığın tamamında sürekli ve düzenli biçimde azalmıştır', 'Bu aralıkta 22 °C\'yi aşmıştır'], 'En düşük değer aralığın başında, en yüksek değer sonundadır. Bu, aralığın genelinde artış eğilimine işaret eder; 22 °C\'nin aşılması ise en yüksek değer bilgisiyle çelişir.'),
  ('Bir f fonksiyonunun eğrisi x eksenini yalnız x = 4\'te kesiyor; bu noktanın solunda eksenin altında, sağında eksenin üstünde kalıyor. f(2)·f(6) çarpımının işareti nedir?', 'Negatif', ['Pozitif', 'Sıfır', 'Belirlenemez'], 'f(2) < 0 ve f(6) > 0 olduğundan çarpım negatiftir.'),
  ('Bir f fonksiyonu x = 2\'de yerel en büyük değerini alıyor ve f(2) = 9\'dur. y = f(x) − 4 fonksiyonu için hangisi kesindir?', 'x = 2\'de yerel en büyük değeri 5\'tir', ['x = −2\'de yerel en büyük değeri 9\'dur', 'x = 6\'da yerel en büyük değeri 9\'dur', 'x = 2\'de yerel en küçük değeri 5\'tir'], 'Düşey öteleme yerel ekstremumların apsisini değiştirmez; değerden 4 çıkar ve 9 − 4 = 5 olur.'),
  ('Gerçek sayılarda tanımlı bir f fonksiyonu kesin artandır. f(x) = 7 denkleminin en çok kaç çözümü olabilir?', '1', ['2', '0', 'Sonsuz sayıda'], 'Kesin artan fonksiyon birebirdir; aynı değeri iki farklı noktada alamaz. Bu yüzden en çok bir çözüm vardır.'),
  ('Bir bitkinin boyu 3. günde 12 cm, 10. günde 33 cm ölçülmüştür. Bu iki ölçüm arasında bitki günde ortalama kaç cm uzamıştır?', '3', ['3,3', '2,1', '4,5'], 'Ortalama uzama (33 − 12)/(10 − 3) = 21/7 = 3 cm/gündür.'),
  ('Doğrusal bir fonksiyonun farklı aralıklardaki ortalama değişim hızları için hangisi doğrudur?', 'Her aralıkta aynıdır ve eğime eşittir', ['Aralık uzadıkça artar', 'Aralık sağa kaydıkça azalır', 'Yalnız orijini içeren aralıkta eğime eşittir'], 'f(x) = mx + n için [f(b) − f(a)]/(b − a) = m olur. Bu, aralık ne olursa olsun sabittir.'),
  ('f(x) = x² − 6x fonksiyonunun [1, a] aralığındaki ortalama değişim hızı 0 olduğuna göre a kaçtır?', '5', ['6', '3', '4,5'], 'f(a) = f(1) olmalıdır: a² − 6a = −5, a² − 6a + 5 = 0, a = 1 ya da a = 5. a ≠ 1 olduğundan a = 5\'tir.'),
  ('Bir arabanın sabah 09.00\'da 120. kilometrede, 11.30\'da 320. kilometrede olduğu biliniyor. Bu sürede ortalama hızı kaç km/sa\'tir?', '80', ['100', '64', '72,5'], '200 km yol 2,5 saatte alınmıştır; ortalama hız 200/2,5 = 80 km/sa\'tir.'),
  ('Periyodu 4 olan bir f fonksiyonu için f(1) = 6 ve f(3) = −2 veriliyor. f(21) + f(−5) toplamı kaçtır?', '4', ['12', '−4', '8'], '21 = 1 + 5·4 olduğundan f(21) = 6\'dır. −5 = 3 − 8 olduğundan f(−5) = −2\'dir. Toplam 4\'tür.'),
  ('Bir dönme dolabın bir kabininin yerden yüksekliği zamana göre çizildiğinde periyodik bir eğri elde edilir. Bu eğride periyot neyi gösterir?', 'Dolabın bir tam tur için harcadığı süreyi', ['Kabinin dönüş sırasında çıkabildiği en yüksek noktanın yüksekliğini', 'Dolabın yarıçapını', 'Kabinin en alçak noktadaki yüksekliğini'], 'Periyot, hareketin aynen tekrar etmesi için geçen süredir; burada bir tam dönüş süresidir.'),
  ('Periyodu 6 olan bir f fonksiyonu aynı zamanda tek fonksiyondur ve f(2) = 5\'tir. f(4) kaçtır?', '−5', ['5', '0', '−2,5'], 'Periyodiklikten f(4) = f(4 − 6) = f(−2)\'dir. Teklikten f(−2) = −f(2) = −5 olur.'),
  ('Her x için f(x + 2) = −f(x) eşitliğini sağlayan bir fonksiyonun periyodu için hangisi kesindir?', '4 sayısı bir periyottur', ['2 sayısı bir periyottur', 'Fonksiyon periyodik olamaz', '8 en küçük periyottur'], 'f(x + 4) = −f(x + 2) = −(−f(x)) = f(x) olduğundan 4 bir periyottur.'),
  ('f fonksiyonu 1 → 3, 2 → 1, 3 → 4, 4 → 2 eşlemesini; g fonksiyonu 1 → 2, 2 → 4, 3 → 1, 4 → 3 eşlemesini yapıyor. (f∘g)(3) kaçtır?', '3', ['4', '1', '2'], 'Önce g uygulanır: g(3) = 1. Sonra f(1) = 3 bulunur.'),
  ('f eşlemesi 1 → 3, 2 → 1, 3 → 4, 4 → 2 ve g eşlemesi 1 → 2, 2 → 4, 3 → 1, 4 → 3 olarak verilmiştir. (g∘f)(2) ile (f∘g)(2) değerlerinin toplamı kaçtır?', '4', ['5', '6', '3'], '(g∘f)(2) = g(f(2)) = g(1) = 2. (f∘g)(2) = f(g(2)) = f(4) = 2. Toplam 4\'tür.'),
  ('Bir mağaza önce fiyata %20 zam yapıyor, sonra zamlı fiyattan 30 TL indirim uyguluyor. Başlangıç fiyatı x için son fiyatı veren bileşke kuralı hangisidir?', '1,2x − 30', ['1,2(x − 30)', '0,8x − 30', '1,2x + 30'], 'Zam f(x) = 1,2x, indirim g(x) = x − 30\'dur. Önce zam, sonra indirim uygulanınca g(f(x)) = 1,2x − 30 olur.'),
  ('Kenar uzunluğu zamana göre a(t) = 2t + 1 cm olan bir karenin alanı A(a) = a² ile hesaplanır. t = 3 saniyede karenin alanı kaç cm²\'dir?', '49', ['36', '7', '42,25'], 'a(3) = 7 cm\'dir. A(7) = 49 cm² olur; bu A∘a bileşkesinin t = 3\'teki değeridir.'),
  ('f(x) = √x ve g(x) = x − 5 için (f∘g)(x) fonksiyonunun en geniş tanım kümesi hangisidir?', '[5, ∞)', ['[0, ∞)', '(5, ∞)', '[−5, ∞)'], '(f∘g)(x) = √(x − 5) olduğundan x − 5 ≥ 0, yani x ≥ 5 gerekir.'),
  ('f(x) = 1/x ve g(x) = x² − 9 için (f∘g)(x) fonksiyonu hangi x değerlerinde tanımsızdır?', 'x = 3 ve x = −3', ['Yalnız x = 0', 'Yalnız x = 3', 'x = 0 ve x = 9'], '(f∘g)(x) = 1/(x² − 9) olur; payda x = ±3\'te sıfırlanır.'),
  ('Bir f fonksiyonu için f(0) = 2, f(2) = 5, f(5) = 0 değerleri biliniyor. (f∘f∘f)(0) kaçtır?', '0', ['5', '2', '10'], 'f(0) = 2, f(2) = 5, f(5) = 0. Üç adım sonra yeniden 0\'a dönülür.'),
  ('Bir trafik lambası 90 saniyelik döngüde önce 40 saniye yeşil, sonra 5 saniye sarı, sonra 45 saniye kırmızı yanıyor. Döngü başladıktan 1 000 saniye sonra lamba hangi renktedir?', 'Yeşil', ['Sarı', 'Kırmızı', 'Kapalı'], '1 000 = 11·90 + 10 olduğundan döngünün 10. saniyesindeyiz. İlk 40 saniye yeşildir.'),
  ('Bir kafede içecek fiyatı, bardak hacmi h (mL) için F(h) = 0,1h + 15 TL\'dir. F⁻¹(45) değeri günlük dilde neyi ifade eder?', '45 TL ödenen içeceğin hacmini', ['300 mL\'lik içeceğin fiyatını', '45 mL\'lik içeceğin fiyatını', 'Fiyatın hacme oranını gösteren birim fiyat değerini'], 'Ters fonksiyon fiyattan hacme gider. 0,1h + 15 = 45 ise h = 300 mL\'dir.'),
  ('Bir sayıyı 3 ile çarpıp 4 çıkaran makinenin işlemini geri alan makine bir sayıya sırasıyla ne yapar?', '4 ekler, sonra 3\'e böler', ['3\'e böler, sonra 4 ekler', '4 çıkarır, sonra 3 ile çarpar', '3 ile çarpar, sonra 4 ekler'], 'Ters işlem adımları ters sırada ve ters işlemlerle yapılır: son yapılan çıkarma önce toplamayla, sonra çarpma bölmeyle geri alınır.'),
  ('(2, 7) noktası y = f(x) grafiği üzerindeyse, f\'nin tersinin grafiği üzerinde kesinlikle hangi nokta bulunur?', '(7, 2)', ['(−2, −7)', '(2, −7)', '(−7, −2)'], 'Ters fonksiyonun grafiği y = x doğrusuna göre simetriktir; koordinatlar yer değiştirir.'),
  ('Kareleme kuralı yalnız negatif olmayan sayılara götürülecek biçimde, f: ℝ → [0, ∞), f(x) = x² olarak tanımlanıyor. Birebirlik ve örtenlik açısından doğru nitelendirme hangisidir?', 'Örtendir ama birebir değildir', ['Birebirdir ama örten değildir', 'Hem birebir hem de örten olan bir fonksiyondur', 'Ne birebir ne örtendir'], 'Her negatif olmayan sayı bir karenin değeridir, bu yüzden örtendir. Ama 2 ve −2 aynı görüntüye gittiğinden birebir değildir.'),
  ('Bir fonksiyonun bir aralıkta kesin artan olması ile birebirliği arasındaki ilişki hangisidir?', 'Kesin artanlık o aralıkta birebirliği garanti eder', ['Birebirlik kesin artanlığı garanti eder', 'İkisi arasında hiçbir ilişki yoktur, biri diğerini etkilemez', 'Kesin artan fonksiyonlar birebir olamaz'], 'x₁ < x₂ için f(x₁) < f(x₂) ise farklı girdiler farklı çıktılar verir. Tersi her zaman doğru değildir; birebir bir fonksiyon azalan da olabilir.'),
  ('f(x) = x² − 1 ve g(x) = x + 1 olmak üzere (f/g)(x) fonksiyonu sadeleştirildiğinde hangi kurala ulaşılır ve hangi noktada tanımsızdır?', 'x − 1; x = −1\'de tanımsızdır', ['x + 1; x = 1\'de tanımsızdır', 'x − 1; hiçbir noktada tanımsız değildir', 'x + 1; x = −1\'de tanımsızdır'], '(x² − 1)/(x + 1) = (x − 1)(x + 1)/(x + 1) = x − 1 olur. g(−1) = 0 olduğundan bölüm x = −1\'de tanımsızdır.'),
  ('f(x) = √(x − 1) ve g(x) = √(5 − x) ise f + g toplam fonksiyonunun en geniş tanım kümesi hangisidir?', '[1, 5]', ['[1, ∞)', '(−∞, 5]', '(1, 5)'], 'Toplam, iki fonksiyonun da tanımlı olduğu yerde tanımlıdır: x ≥ 1 ve x ≤ 5 kesişimi [1, 5]\'tir.'),
  ('Her x için f(x) − f(x − 1) = 2 ve f(0) = 3 eşitliklerini sağlayan f için f(10) kaçtır?', '23', ['20', '13', '30'], 'Her birim adımda değer 2 artar. 10 adımda 3 + 10·2 = 23 olur.'),
  ('Her x, y için f(x + y) = f(x) + f(y) eşitliğini sağlayan bir fonksiyon için f(0) kaçtır?', '0', ['1', '−1', 'Belirlenemez'], 'x = y = 0 alınırsa f(0) = 2f(0) olur; buradan f(0) = 0 bulunur.'),
  ('Karekök eğrisi y = √x ile eğimi 1/2 olup orijinden geçen doğru kaç ortak noktaya sahiptir?', '2', ['1', '0', '3'], '√x = x/2 ise x = x²/4, yani x(x − 4) = 0 olur. x = 0 ve x = 4 olmak üzere iki kesişim noktası vardır.'),
  ('Küpkök fonksiyonu y = ∛x ile karekök fonksiyonu y = √x arasındaki temel fark hangisidir?', 'Küpkök negatif girdiler için de tanımlıdır', ['Küpkök yalnız pozitif değer alır', 'Karekök fonksiyonu bütün gerçek sayılarda tanımlıdır', 'Küpkök azalan bir fonksiyondur'], 'Negatif bir sayının küpkökü gerçek bir sayıdır, örneğin ∛(−8) = −2. Karekök ise negatif sayılarda gerçek değildir.'),
  ('Sabit hacimde bir gazın basıncı ile hacmi ters orantılıdır: P = 120/V. Hacim 4 katına çıkarılırsa basınç nasıl değişir?', 'Dörtte birine iner', ['4 katına çıkar', 'Yarıya iner', 'Değişmez'], 'P ile V çarpımı sabittir. V 4 katına çıkınca P\'nin 4\'e bölünmesi gerekir.'),
  ('Bir işi 6 işçi 20 günde bitiriyor. İşçi sayısı n ile gün sayısı g arasındaki ilişkiyi veren fonksiyon hangisidir?', 'g = 120/n', ['g = 20n/6', 'g = 120n', 'g = 6n + 20'], 'Toplam iş 6·20 = 120 işçi-gündür. Gün sayısı işçi sayısıyla ters orantılıdır: g = 120/n.'),
  ('f(x) = 3ˣ ile g(x) = 5ˣ grafikleri karşılaştırıldığında x > 0 bölgesi için hangisi doğrudur?', 'g\'nin grafiği f\'ninkinin üstündedir', ['f\'nin grafiği g\'ninkinin üstündedir', 'İki grafik çakışıktır', 'İki grafik bu bölgede bir noktada kesişir ve yer değiştirir'], 'x > 0 için 5ˣ > 3ˣ\'tir. İki grafik yalnız (0, 1) noktasında kesişir; x < 0\'da sıralama tersine döner.'),
  ('İkinin kuvvetlerini veren 2ˣ ifadesinde üs eksi sonsuza doğru küçüldükçe eğri nasıl bir davranış gösterir?', 'x eksenine yaklaşır ama onu kesmez', ['x eksenini bir noktada keser', 'Negatif değerlere iner ve sınırsız biçimde küçülür', 'y eksenine yaklaşır'], '2ˣ her zaman pozitiftir; x çok küçüldükçe değerler sıfıra yaklaşır. x ekseni (y = 0) yatay asimptottur.'),
  ('2\'nin kuvvetlerinden 8 çıkaran y = 2ˣ − 8 kuralının sıfırı, yani eğrinin yatay ekseni kestiği nokta hangisidir?', '(3, 0)', ['(8, 0)', '(4, 0)', '(−3, 0)'], '2ˣ = 8 ise x = 3\'tür.'),
  ('x yerine 0 yazıldığında 3^(x+2) üstel ifadesi hangi değeri verir; yani bu eğri dikey ekseni nerede keser?', '(0, 9)', ['(0, 1)', '(0, 3)', '(0, 6)'], 'x = 0 için y = 3² = 9 bulunur.'),
  ('Bir otomobilin değeri her yıl bir önceki yılın %20\'si kadar azalıyor. Bugün 500 000 TL olan aracın 2 yıl sonraki değeri kaç TL olur?', '320 000', ['300 000', '400 000', '360 000'], 'Her yıl değer 0,8 ile çarpılır: 500 000·0,8² = 500 000·0,64 = 320 000 TL.'),
  ('Bir ilacın kandaki miktarı her 4 saatte yarıya iniyor. 160 mg\'lık doz alındıktan 12 saat sonra kanda kaç mg ilaç kalır?', '20', ['40', '80', '53,3'], '12 saat 3 yarılanma süresidir: 160 → 80 → 40 → 20 mg.'),
  ('Bir kasabanın nüfusu her yıl %10 artıyor. Nüfus 2 yılda başlangıca göre yüzde kaç artmış olur?', '21', ['20', '10', '11'], 'Her yıl 1,1 ile çarpılır: 1,1² = 1,21. Toplam artış %21\'dir.'),
  ('Bir miktarın değerleri yıllara göre 100, 120, 144, 172,8 olarak ölçülmüştür. Bu değişim için en uygun yorum hangisidir?', 'Her yıl %20 artan üstel bir büyümedir', ['Her yıl 20 birim artan doğrusal büyümedir', 'Her yıl artış miktarı sabit olan büyümedir', 'Önce artan sonra azalan bir değişimdir'], 'Ardışık oranlar 120/100 = 144/120 = 172,8/144 = 1,2\'dir. Oran sabit olduğundan büyüme üsteldir.'),
  ('f(n) = 50n ve g(n) = 2ⁿ fonksiyonları için g(n) > f(n) eşitsizliğini sağlayan en küçük pozitif tam sayı n kaçtır?', '9', ['8', '10', '6'], 'n = 8: 256 < 400; n = 9: 512 > 450. İlk kez n = 9\'da üstel fonksiyon öne geçer.'),
  ('Bir ölçüm listesinde x her 1 arttığında y\'nin değeri 3 ile çarpılıyorsa x ile y arasındaki ilişki hangi biçimdedir?', 'y = a·3ˣ', ['y = 3x + a', 'y = a·x³', 'y = a/3x'], 'Girdideki sabit artışa çıktıda sabit çarpan karşılık geliyorsa ilişki üsteldir ve taban 3\'tür.'),
  ('f ve g fonksiyonlarının grafikleri yalnız x = −1 ve x = 4\'te kesişiyor; −1 < x < 4 aralığında f\'nin grafiği g\'ninkinin üstünde, dışında ise altında kalıyor. f(x) − g(x) < 0 eşitsizliğinin çözüm kümesi nedir?', '(−∞, −1) ∪', ['(−1, 4)', '[−1, 4]', '(−∞, −1] ∪ [4, ∞)'], 'f − g < 0, f\'nin g\'nin altında olduğu yerlerdir. Kesişim noktalarında fark sıfır olduğundan bu noktalar dahil edilmez.'),
  ('x² > 4x eşitsizliğinin çözümü, y = x² ve y = 4x eğrilerinin konumu düşünülerek bulunursa hangisi elde edilir?', '(−∞, 0) ∪', ['(0, 4)', '(4, ∞)', '(−∞, 0] ∪ [4, ∞)'], 'Eğriler x = 0 ve x = 4\'te kesişir. Bu iki noktanın arasında doğru parabolün üstünde, dışında ise parabol doğrunun üstündedir.'),
  ('Pozitif x için 2ˣ ile x² karşılaştırıldığında 2ˣ < x² eşitsizliği hangi aralıkta sağlanır?', '(2, 4)', ['(0, 2)', '(4, ∞)', '(1, 3) aralığında'], 'Eğriler x = 2 (4 = 4) ve x = 4\'te (16 = 16) kesişir. Arada, örneğin x = 3\'te 8 < 9 olur; dışında 2ˣ büyüktür.'),
  ('max{a, b}, a ve b\'den büyük olanı göstermek üzere f(x) = max{x, 3 − x} için f(0) + f(5) toplamı kaçtır?', '8', ['3', '5', '6'], 'f(0) = max{0, 3} = 3 ve f(5) = max{5, −2} = 5\'tir. Toplam 8 olur.'),
  ('sgn(x) işaret fonksiyonu x > 0 için 1, x = 0 için 0, x < 0 için −1 değerini alır. sgn(x² − 9) fonksiyonunun x = 2\'deki değeri kaçtır?', '−1', ['1', '0', '−5'], '2² − 9 = −5 negatif olduğundan işaret fonksiyonu −1 verir.'),
  ('Kenarı 12 cm olan kare bir kartonun köşelerinden kenarı x cm olan kareler kesilip kenarlar katlanarak üstü açık bir kutu yapılıyor. Kutunun hacmini x cinsinden veren fonksiyon hangisidir?', 'V(x) = x(12 − 2x)²', ['V(x) = x(12 − x)²', 'V(x) = x²(12 − 2x)', 'V(x) = (12 − 2x)³ / x'], 'Taban kenarı 12 − 2x, yükseklik x olur. Hacim taban alanı ile yüksekliğin çarpımıdır: x(12 − 2x)².'),
  ('Kenarı 12 cm olan karton kareden, köşelerden x cm\'lik kareler kesilerek kutu yapılıyor. Hacim fonksiyonunun anlamlı tanım kümesi hangisidir?', '(0, 6)', ['(0, 12)', '[0, 6]', '(6, 12)'], 'Kesilen kare pozitif olmalı (x > 0) ve taban kenarı 12 − 2x pozitif kalmalıdır (x < 6).'),
  ('Bir çerçeveci kare biçimli çerçevelerin camını çevre uzunluğuna göre fiyatlandırıyor. Karenin alanını çevresi P cinsinden veren fonksiyon hangisidir?', 'A(P) = P²/16', ['A(P) = P²/4', 'A(P) = 4P²', 'A(P) = P/16'], 'Karenin kenarı P/4\'tür; alanı (P/4)² = P²/16 olur.'),
  ('Bir küpün yüzey alanını kenar uzunluğu a cinsinden veren S(a) = 6a² fonksiyonunda kenar 3 katına çıkarsa yüzey alanı nasıl değişir?', '9 katına çıkar', ['3 katına çıkar', '6 katına çıkar', '27 katına çıkar'], 'S(3a) = 6·9a² = 9·S(a) olur; alan uzunluğun karesiyle orantılıdır.'),
  ('Uzunluğu 20 m olan bir telin bir parçası x m\'lik kare yapılıyor, kalan parçası ise kare yapılmadan bırakılıyor. Karenin alanını tel parçası x cinsinden veren fonksiyon hangisidir?', 'x²/16', ['x²/4', '(20 − x)²/16', 'x²'], 'x m\'lik telden yapılan karenin kenarı x/4\'tür; alanı x²/16 olur.'),
  ('Sözel olarak şöyle betimlenen bir fonksiyon hangisi olabilir: \'Bütün gerçek sayılarda tanımlı, her zaman pozitif, x büyüdükçe sınırsız artan, x küçüldükçe sıfıra yaklaşan.\'', 'y = 3ˣ', ['y = x²', 'y = 3x', 'y = log₃x'], 'Her yerde pozitif olup sol tarafta sıfıra yaklaşan, sağda hızla artan eğri üstel fonksiyona aittir. x² sol tarafta da büyür.'),
  ('\'Yalnız pozitif sayılarda tanımlı, x = 1\'de sıfır, yavaşça ve sınırsız artan\' biçiminde betimlenen fonksiyon hangisidir?', 'y = ln x', ['y = eˣ', 'y = √x', 'y = 1/x'], 'ln x yalnız x > 0\'da tanımlıdır, ln 1 = 0\'dır ve çok yavaş da olsa sınırsız artar. √x ise x = 0\'da tanımlıdır ve x = 1\'de 1 değerini alır.'),
  ('\'Gerçek sayılarda tanımlı, orijine göre simetrik, birebir ve görüntü kümesi bütün gerçek sayılar\' olan fonksiyon hangisidir?', 'y = x³', ['y = x²', 'y = 2ˣ', 'y = |x|'], 'x³ tek fonksiyondur, kesin artandır (birebir) ve her gerçek değeri alır. Diğerlerinin görüntü kümesi sınırlıdır.'),
  ('Bir doğrusal fonksiyonun grafiği x eksenini 4\'te, y eksenini −2\'de kesiyor. Bu fonksiyonun kuralı hangisidir?', 'y = x/2 − 2', ['y = 2x − 4', 'y = −x/2 + 4', 'y = −2x + 4'], '(4, 0) ve (0, −2) noktalarından eğim (0 − (−2))/(4 − 0) = 1/2 bulunur; y kesişimi −2\'dir.'),
  ('V biçimli bir grafiğin tepe noktası (2, −3)\'tür ve grafik (4, 1) noktasından geçer. Grafik y = a|x − 2| − 3 biçiminde olduğuna göre a kaçtır?', '2', ['1', '4', '−2'], '1 = a·|4 − 2| − 3 ise 2a = 4, a = 2\'dir.'),
  ('Bir üstel fonksiyon y = a·bˣ biçimindedir; grafiği (0, 5) ve (2, 45) noktalarından geçiyor. b kaçtır (b > 0)?', '3', ['9', '5', '4,5'], 'x = 0\'da y = a = 5\'tir. 5·b² = 45 ise b² = 9, b = 3 olur.'),
  ('Kökleri −1 ve 3 olan ve y eksenini (0, 6) noktasında kesen y = a(x + 1)(x − 3) fonksiyonunda a kaçtır?', '−2', ['2', '−6', '3'], 'x = 0 için a·1·(−3) = 6 olur; −3a = 6, a = −2\'dir.'),
  ('y = k/x + m fonksiyonunun grafiği (1, 5) ve (2, 3) noktalarından geçiyor. k + m toplamı kaçtır?', '5', ['4', '1', '6'], 'k + m = 5 ve k/2 + m = 3 denklemleri çıkarılırsa k/2 = 2, k = 4 ve m = 1 bulunur. k + m = 5\'tir; bu zaten x = 1\'deki değerdir.'),
  ('Bir sınıfta \'çıktısı her girdide 7 olan\' bir kural tartışılıyor. Bu kural hangi tür fonksiyona örnektir ve grafiği nedir?', 'Sabit fonksiyon; y = 7 yatay doğrusu', ['Birim fonksiyon; y = x doğrusu', 'Doğrusal fonksiyon; eğimi 7 olan doğru', 'Sabit fonksiyon; x = 7 düşey doğrusu'], 'Girdiye bakmadan hep aynı çıktıyı veren kural sabit fonksiyondur. Grafiği y = 7 yatay doğrusudur; x = 7 ise fonksiyon grafiği değildir.'),
  ('Yarıçapı r cm, yüksekliği 10 cm olan silindirin hacmini veren fonksiyon V(r) = 10πr² ise yarıçap 3 cm\'den 6 cm\'ye çıkınca hacim kaç katına çıkar?', '4', ['2', '8', '3'], 'V(6)/V(3) = 36/9 = 4\'tür. Hacim yarıçapın karesiyle orantılıdır.'),
  ('Bir bisikletlinin evden uzaklığı ilk 20 dakikada 0\'dan 6 km\'ye doğrusal artıyor, sonraki 10 dakikada 6 km\'de sabit kalıyor, son 30 dakikada doğrusal olarak 0\'a iniyor. Bisikletli dönüş yolunda saatte kaç km hızla gitmiştir?', '12', ['18', '6', '9'], 'Dönüşte 6 km yol 30 dakikada, yani yarım saatte alınmıştır: 6/0,5 = 12 km/sa.'),
  ('Uzaklığı zamanla değişen bir yürüyüşçünün uzaklık-zaman eğrisinde yatay bir bölüm görülüyor. Bu bölüm sırasında yürüyüşçü ne yapmaktadır?', 'Durmaktadır; uzaklığı değişmemektedir', ['Sabit hızla başlangıç noktasından uzaklaşmaktadır', 'Başlangıç noktasına dönmektedir', 'Hızlanarak ilerlemektedir'], 'Yatay bölümde zaman geçtiği hâlde uzaklık aynı kalır. Bu, hareketin durduğunu gösterir.'),
  ('Bir atölyenin aylık sabit gideri 9 000 TL, ürün başına maliyeti 40 TL, ürün satış fiyatı 100 TL\'dir. Başabaş noktası (kârın sıfır olduğu üretim) kaç üründür?', '150', ['90', '225', '180'], 'Kâr = 100x − (9 000 + 40x) = 60x − 9 000. Sıfır olması için x = 150 ürün gerekir.'),
  ('Talep fonksiyonu T(p) = 500 − 4p olan bir ürün için fiyat 1 TL artınca talep nasıl değişir?', '4 adet azalır', ['4 adet artar', '500 adet azalır', '%4 azalır'], 'Doğrusal talep fonksiyonunun eğimi −4\'tür; fiyattaki her 1 TL\'lik artış talebi 4 adet düşürür.'),
  ('Bir kafede bilet fiyatı x TL iken satılan bilet sayısı 200 − 2x\'tir. Fiyat 40 TL olduğunda elde edilen toplam gelir kaç TL\'dir?', '4 800', ['8 000', '5 200', '3 600'], 'Satılan bilet 200 − 80 = 120 adettir. Gelir 120·40 = 4 800 TL\'dir.'),
  ('Kâr fonksiyonu K(x) = 25x − 3 000 olan bir işletme için grafiğin x eksenini kestiği nokta neyi temsil eder?', 'Kârın sıfır olduğu üretim miktarını', ['Sabit gider tutarını', 'Bir ürünün satışından elde edilen birim kâr miktarını', 'En yüksek kârı'], 'x ekseniyle kesişimde K(x) = 0\'dır; bu noktanın altında zarar, üstünde kâr vardır. 3 000 sabit gider, 25 birim kârdır.'),
  ('Bir yayın uzaması, asılan kütleyle doğru orantılıdır. 200 g\'lık kütle yayı 5 cm uzatıyorsa 680 g\'lık kütle kaç cm uzatır?', '17', ['13,6', '20', '15'], 'Uzama/kütle oranı 5/200 = 0,025 cm/g\'dır. 680·0,025 = 17 cm olur.'),
  ('Bir direnç üzerindeki gerilim V = 15I volt (I amper) ile veriliyor. Gerilim 9 V olduğunda akım kaç amperdir?', '0,6', ['135', '1,67', '6'], '9 = 15I ise I = 9/15 = 0,6 A\'dir.'),
  ('Bir depoda başta 800 litre yakıt var ve jeneratör saatte 35 litre tüketiyor. Depoda 100 litre kaldığında uyarı veriliyor. Uyarı çalıştırmadan kaç saat sonra gelir?', '20', ['22,9', '25', '17'], '800 − 35t = 100 ise 35t = 700, t = 20 saattir.'),
  ('Bir tekstil atölyesinde günlük üretim adedi çalışan sayısı n için Ü(n) = 45n\'dir. Ü(8) − Ü(6) farkı neyi ifade eder ve kaçtır?', '2 ek çalışanın sağladığı üretim artışı; 90', ['8 çalışanın bir günde ürettiği toplam ürün sayısı; 360', '6 çalışanın toplam üretimi; 270', 'Bir çalışanın günlük üretimi; 45'], 'Ü(8) = 360, Ü(6) = 270\'tir. Fark 90 olup çalışan sayısının 6\'dan 8\'e çıkmasıyla oluşan artıştır.'),
  ('Bir arabanın t saatte aldığı yol s(t) km\'dir. s(3) = 210 ifadesinin anlamı hangisidir?', 'Araç 3 saatte 210 km yol almıştır', ['Araç 210 saatte 3 km yol almıştır', 'Aracın saatteki ortalama hızının 210 km olduğunu gösterir', 'Araç 3. saatte durmuştur'], 's\'nin girdisi zaman, çıktısı yoldur. s(3) = 210, 3 saatlik sürede alınan yolun 210 km olduğunu söyler.'),
  ('Bir yüzme havuzu saatte 3 m³ su alan bir hortumla dolduruluyor ve havuzda başlangıçta 12 m³ su var. Havuzdaki su miktarı 30 m³ olduğunda kaç saat geçmiştir?', '6', ['10', '4', '14'], '12 + 3t = 30 ise t = 6 saattir.'),
  ('Bir öğrenci f(x + 2) ile f(x) + 2 ifadelerinin her zaman eşit olduğunu düşünüyor. f(x) = x² için x = 1\'de bu iki ifadenin değerleri nedir?', '9 ve 3', ['3 ve 3', '9 ve 9', '4 ve 3'], 'f(3) = 9, f(1) + 2 = 3\'tür. Girdiye 2 eklemek ile çıktıya 2 eklemek farklı işlemlerdir.'),
  ('(a, 7) noktası y = 3x + 1 doğrusu üzerinde, (2, b) noktası ise aynı doğrunun ters fonksiyonunun grafiği üzerindedir. a + b toplamı kaçtır?', '7/3', ['9', '3', '5/3'], '3a + 1 = 7 ise a = 2. Ters fonksiyonda (2, b) noktası, asıl fonksiyonda (b, 2) demektir: 3b + 1 = 2, b = 1/3. Toplam 7/3\'tür.'),
  ('y = mx + n doğrusu ikinci bölgeden geçmiyorsa m ve n için hangisi kesinlikle doğrudur?', 'm ≥ 0 ve n ≤ 0', ['m < 0 ve n > 0', 'm > 0 ve n > 0', 'm ≤ 0 ve n ≥ 0'], 'İkinci bölge x < 0, y > 0\'dır. Doğru buraya girmemek için x eksi sonsuza giderken yükselmemeli (m ≥ 0) ve y kesişimi pozitif olmamalıdır (n ≤ 0).'),
  ('Gerçek sayılarda azalan bir f fonksiyonu için f(3x − 2) > f(x + 4) eşitsizliğinin çözüm kümesi nedir?', 'x < 3', ['x > 3', 'x < 1', 'x > 1'], 'Azalan fonksiyonda daha büyük değer daha küçük girdiden gelir: 3x − 2 < x + 4, yani x < 3.'),
  ('f(x) = 5 − 0,5x fonksiyonu için f(√2), f(1) ve f(2) değerlerinin büyükten küçüğe sıralaması hangisidir?', 'f(1) > f(√2) > f(2)', ['f(2) > f(√2) > f(1)', 'f(√2) > f(1) > f(2)', 'f(1) > f(2) > f(√2)'], 'Fonksiyon azalandır; küçük girdi büyük çıktı verir. 1 < √2 < 2 olduğundan sıralama f(1) > f(√2) > f(2)\'dir.'),
  ('Gerçek sayılarda artan bir f fonksiyonu için f(a) = f(b) ise a ile b arasında hangi ilişki kesindir?', 'a = b', ['a < b', 'a > b', 'a = −b'], 'Kesin artan fonksiyon birebirdir; aynı çıktıyı veren iki girdi eşit olmak zorundadır.'),
  ('(1, 4) noktası f\'nin eğrisindedir. Girdisi önce 3\'ten çıkarılan, çıktısı da iki katına çıkarılan y = 2f(3 − x) eğrisinde kesinlikle hangi nokta vardır?', '(2, 8)', ['(−2, 8)', '(1, 8)', '(2, 4)'], '3 − x = 1 için x = 2\'dir; bu noktada y = 2·f(1) = 8 olur.'),
  ('Kesirli terimi 2/(x² + 1) olan 3 − 2/(x² + 1) ifadesi x gerçek sayısı değiştikçe hangi değerleri alır?', '[1, 3)', ['(1, 3]', '[1, 3]', '(0, 3)'], '2/(x² + 1) değeri (0, 2] aralığındadır; x = 0\'da 2\'ye eşittir. Bu yüzden 3 − 2/(x² + 1) değeri [1, 3) aralığındadır.'),
  ('Bir fabrikada üretilen vidaların boyu 40 mm olmalıdır ve en çok 0,5 mm sapmaya izin verilir. Kabul edilen boylar x için hangi eşitsizlikle ifade edilir?', '|x − 40| ≤ 0,5', ['|x + 40| ≤ 0,5', '|x − 0,5| ≤ 40', '|x − 40| ≥ 0,5'], 'İstenen değere uzaklık en çok 0,5 mm olmalıdır: |x − 40| ≤ 0,5, yani 39,5 ≤ x ≤ 40,5.'),
  ('f(x) = |x − 2| + |x − 8| fonksiyonu hangi aralıkta sabit değer alır ve bu değer kaçtır?', '[2, 8] aralığında, 6', ['[2, 8] aralığında, 10', '(−∞, 2] aralığında, 6', '[0, 8] aralığında, 8'], 'x, 2 ile 8 arasındayken iki uzaklığın toplamı bu noktalar arasındaki uzaklığa, yani 6\'ya eşittir.'),
  ('Bir postanede mektup ücreti her başlamış 20 gram için 15 TL\'dir. 47 gramlık bir mektubun ücreti kaç TL\'dir?', '45', ['30', '35,25', '60'], '47/20 = 2,35\'tir; başlamış dilim sayısı 3\'tür. Ücret 3·15 = 45 TL\'dir.'),
  ('Bir telefon görüşmesi her başlamış dakika için ücretlendiriliyor. Görüşme süresi-ücret grafiği nasıl görünür?', 'Her tam dakikadan sonra yukarı sıçrayan basamaklar', ['Orijinden geçen eğik bir doğru', 'Gittikçe yataylaşan, kesintisiz ve sürekli yükselen bir eğri', 'Her dakikada aşağı inen basamaklar'], 'Ücret bir dakika boyunca sabit kalır, yeni dakika başlar başlamaz bir birim artar; bu, yukarı doğru basamak grafiğidir.'),
  ('Bir şehirde sıcaklık saat 08.00\'de 12 °C, 12.00\'de 20 °C ölçülmüştür. Arada sıcaklığın doğrusal değiştiği varsayılırsa saat 09.30\'daki tahmini sıcaklık kaç °C\'dir?', '15', ['16', '14', '13,5'], 'Saatte (20 − 12)/4 = 2 °C artış vardır. 1,5 saatte 3 °C artarak 15 °C olur.'),
  ('Bir yükseklik ölçerin gösterdiği basınç deniz seviyesinde 1 013 hPa, 1 000 m yükseklikte 899 hPa\'dır. Arada doğrusal değişim varsayılırsa 500 m\'deki basınç tahmini kaç hPa\'dır?', '956', ['950', '957,5', '944'], 'İki değerin ortalaması alınır: (1 013 + 899)/2 = 956 hPa.'),
  ('Bir arabanın hızı km/sa cinsinden v ise m/s cinsinden hızı veren fonksiyon hangisidir?', 'v/3,6', ['3,6v', 'v/60', '1 000v/60'], '1 km/sa = 1 000 m / 3 600 s = 1/3,6 m/s\'dir.'),
  ('Bir dükkânda kumaşın metre fiyatı 90 TL\'dir. Santimetre cinsinden uzunluk x için fiyatı TL olarak veren fonksiyon hangisidir?', '0,9x', ['90x', '9x', '0,09x'], '1 m = 100 cm olduğundan santimetre fiyatı 90/100 = 0,9 TL\'dir.'),
  ('y = 2ˣ grafiğini 3 birim aşağı kaydırınca oluşan eğrinin yatay asimptotu ve y eksenini kestiği nokta hangisidir?', 'y = −3 ve (0, −2)', ['y = 3 ve (0, 4)', 'y = −3 ve (0, −3)', 'y = 0 ve (0, −2)'], 'y = 2ˣ − 3 için asimptot y = −3\'tür. x = 0\'da 1 − 3 = −2 olur.'),
  ('y = log₂x grafiği 4 birim sola kaydırılıp 1 birim yukarı çıkarılırsa x eksenini hangi noktada keser?', '(−3,5; 0)', ['(−3; 0)', '(−5; 0)', '(4,5; 0)'], 'Yeni fonksiyon log₂(x + 4) + 1\'dir. log₂(x + 4) = −1 ise x + 4 = 1/2, x = −3,5\'tir.'),
  ('Sayı doğrusunda 1 ve 9 noktalarına eşit uzaklıktaki noktayı bulmak için hangi denklem çözülür?', '|x − 1| = |x − 9|', ['|x + 1| = |x + 9|', '|x − 1| + |x − 9| = 0', '|x| = 10'], 'Bir noktanın 1\'e uzaklığı |x − 1|, 9\'a uzaklığı |x − 9|\'dur. Eşitlik x = 5 verir.'),
  ('Bir tabela üreticisinin verilerine göre 10 harflik bir yazı 300 TL, 25 harflik yazı 525 TL\'dir. Ücret harf sayısının doğrusal fonksiyonu ise 16 harflik yazı kaç TL tutar?', '390', ['480', '336', '405'], 'Harf başına ücret (525 − 300)/15 = 15 TL\'dir. 16 harf: 300 + 6·15 = 390 TL.'),
  ('Artan bir f fonksiyonunun grafiği (1, 2), (3, 5) ve (6, 9) noktalarından geçiyor. f⁻¹(5) + f⁻¹(9) kaçtır?', '9', ['14', '4', '8,5'], 'f(3) = 5 olduğundan f⁻¹(5) = 3; f(6) = 9 olduğundan f⁻¹(9) = 6\'dır. Toplam 9\'dur.'),
  ('f fonksiyonu yalnız [0, 5] aralığında tanımlıdır. g(x) = f(x + 1) fonksiyonunun tanım kümesi nedir?', '[−1, 4]', ['[1, 6]', '[0, 5]', '[−1, 6]'], '0 ≤ x + 1 ≤ 5 olmalıdır; bu −1 ≤ x ≤ 4 verir.'),
  ('Bir aracın hızı ilk 10 saniye boyunca 20 m/s\'de sabit, sonraki 5 saniyede düzgün biçimde 0\'a iniyor. Araç bu 15 saniyede toplam kaç metre yol alır?', '250', ['300', '200', '275'], 'Sabit hızlı bölümde 20·10 = 200 m, yavaşlama bölümünde ortalama hız 10 m/s ile 5 saniyede 50 m alınır. Toplam 250 m\'dir.'),
  ('Bir otoparkta doluluk oranı D(t) gün içindeki saat t\'nin fonksiyonudur. D(14) > D(9) ifadesi ne söyler?', 'Saat 14\'te doluluk saat 9\'dakinden fazladır', ['Doluluk 9 saatte 14 artmıştır', 'Saat 14 ile 9 arasında doluluk hep artmıştır', 'Otopark saat 14\'te tamamen doludur'], 'İfade yalnız iki andaki değerleri karşılaştırır; aradaki değişim hakkında bilgi vermez.'),
  ('f(x) = x + 2 ve g(x) = 3x olmak üzere y = (g∘f)(x) grafiğinin eğimi ve y kesişimi hangisidir?', 'Eğim 3, y kesişimi 6', ['Eğim 3, y kesişimi 2', 'Eğim 1, y kesişimi 6', 'Eğim 4, y kesişimi 2'], 'g(f(x)) = 3(x + 2) = 3x + 6\'dır.'),
  ('Bir yüzücünün hız-zaman eğrisinde ilk 20 saniyelik bölüm yükselen, sonraki bölüm yatay. Bu bilgiye göre yüzücü ilk 20 saniyede ne yapmıştır?', 'Hızlanmıştır', ['Sabit hızla yüzmüştür', 'Durmuştur', 'Yavaşlamıştır'], 'Hız-zaman eğrisinin yükselmesi hızın arttığını, yani hızlanmayı gösterir.'),
  ('Doğru orantılı iki büyüklük için y = kx modelinde x = 8 iken y = 6\'dır. x = 20 iken y kaçtır?', '15', ['18', '26,7', '12'], 'k = 6/8 = 0,75\'tir. y = 0,75·20 = 15 bulunur.'),
  ('x çok büyük değerler alırken log x, √x, x² ve 2ˣ fonksiyonlarından en yavaş büyüyen hangisidir?', 'log x', ['√x', 'x²', '2ˣ'], 'Logaritma, herhangi bir pozitif kuvvetten (√x dahil) daha yavaş büyür. Üstel fonksiyon ise her kuvvetten hızlı büyür.'),
  ('x = 100 için log x, √x, x² ve 2ˣ değerleri küçükten büyüğe nasıl sıralanır? (log on tabanlıdır.)', 'log x < √x < x² < 2ˣ', ['√x < log x < x² < 2ˣ', 'log x < √x < 2ˣ < x²', 'log x < x² < √x < 2ˣ'], 'log 100 = 2, √100 = 10, 100² = 10 000, 2¹⁰⁰ ise yaklaşık 1,27·10³⁰\'dur.'),
  ('Bir karenin kenarını alanı A cinsinden veren fonksiyon s(A) = √A\'dır. Alan 2,25 katına çıkarılırsa kenar uzunluğu kaç katına çıkar?', '1,5', ['2,25', '5,0625', '1,125'], 's(2,25A) = √2,25·√A = 1,5·√A olur. Kenar, alanın kareköküyle orantılıdır.'),
  ('pH = −log[H⁺] tanımına göre pH değeri 3 olan bir çözeltinin H⁺ derişimi, pH değeri 5 olan çözeltininkinin kaç katıdır?', '100', ['2', '1/100', '15'], '[H⁺] = 10^(−pH)\'dir. 10⁻³/10⁻⁵ = 10² = 100\'dür.'),
  ('Logaritmik ölçekli bir eksen üzerinde eşit aralıklarla dizilmiş işaretler neyi gösterir?', 'Değerlerin aynı oranda (örneğin 10 kat) değişmesini', ['Değerlerin aynı miktarda artmasını', 'Değerlerin sabit kalmasını', 'Değerlerin sıfıra yaklaşmasını'], 'Logaritmik ölçekte 1, 10, 100, 1 000 gibi değerler eşit aralıklarla yerleşir; eşit aralık eşit çarpan demektir.'),
  ('Bir cismin h metre yükseklikten serbest düşüş süresi yaklaşık t(h) = √(h/5) saniyedir. 80 m\'den bırakılan cisim kaç saniyede yere ulaşır?', '4', ['16', '8', '2'], 't = √(80/5) = √16 = 4 saniyedir.'),
  ('t(h) = √(h/5) modeline göre düşüş süresi 3 saniyeden 6 saniyeye çıkarsa yükseklik nasıl değişir?', '4 katına çıkar', ['2 katına çıkar', '9 katına çıkar', '√2 katına çıkar'], 'h = 5t²\'dir. t iki katına çıkınca h, 2² = 4 katına çıkar: 45 m\'den 180 m\'ye.'),
  ('I(d) = 360/d² modeline göre d = 2\'den d = 6\'ya geçildiğinde I değeri 90\'dan kaça düşer?', '10', ['30', '45', '60'], 'I(6) = 360/36 = 10\'dur.'),
  ('M(x) = 2 000 + 5x toplam maliyetinde 400 ürün üretildiğinde birim başına ortalama maliyet kaç TL\'dir?', '10', ['5', '25', '7,5'], 'M(400) = 2 000 + 2 000 = 4 000 TL\'dir. 4 000/400 = 10 TL olur.'),
  ('x değerleri 0, 1, 2, 3 iken y değerleri 7, 10, 13, 16 olarak ölçülüyor. Bu veri hangi kurala uyar?', 'y = 3x + 7', ['y = 7·3ˣ', 'y = 7x + 3', 'y = x² + 7'], 'Ardışık farklar sabit (3) olduğundan ilişki doğrusaldır; x = 0\'daki değer 7 sabit terimdir.'),
  ('Bir ilişkide x her 2 birim arttığında y her seferinde 5 birim azalıyor. Bu ilişkinin grafiği nasıldır?', 'Eğimi −2,5 olan bir doğru', ['Eğimi −5 olan bir doğru', 'Eğimi 2,5 olan bir doğru', 'Azalan ve x eksenine yaklaşan üstel bir eğri'], 'Sabit girdi artışına sabit çıktı değişimi doğrusal ilişki demektir; eğim −5/2 = −2,5\'tir.'),
  ('f(f(x)) = x eşitliğini her x için sağlayan bir f fonksiyonunun grafiği için hangisi kesindir?', 'y = x doğrusuna göre simetriktir', ['Orijine göre, yani başlangıç noktasına göre simetriktir', 'y eksenine göre simetriktir', 'x eksenine göre simetriktir'], 'f(f(x)) = x ise f = f⁻¹\'dir; bir fonksiyonun grafiği ile tersininki y = x\'e göre simetrik olduğundan grafik kendisine bu doğruya göre simetriktir.'),
  ('Bir hesap makinesinde bir sayıya \'yarısını al ve 6 ekle\' işlemi tekrar tekrar uygulanıyor. İşlemin sonucu değiştirmediği sayı (f(x) = x) kaçtır?', '12', ['6', '3', '24'], 'x/2 + 6 = x ise x/2 = 6, x = 12\'dir. Bu sayıya işlem uygulandığında yine 12 elde edilir.'),
  ('f(x) = x + 3 fonksiyonunun sabit noktası (f(x) = x eşitliğini sağlayan x) için ne söylenebilir?', 'Sabit noktası yoktur', ['Sabit noktası 3\'tür', 'Sabit noktası −3\'tür', 'Her x sabit noktadır'], 'x + 3 = x eşitliği 3 = 0 çelişkisine yol açar. Grafiği y = x\'e paralel olduğundan bu doğruyu kesmez.'),
  ('f: ℝ → ℝ, f(x) = 2ˣ fonksiyonunu örten yapmak için değer kümesi hangi küme olarak seçilmelidir?', '(0, ∞)', ['[0, ∞)', '[1, ∞)', '(−∞, ∞)'], '2ˣ yalnız pozitif değerler alır ve her pozitif değeri alır. Değer kümesi (0, ∞) seçilirse fonksiyon örten olur.'),
  ('Bir şifreleme önce harf sırasını 3 ileri kaydırıyor, sonra harfleri ters sırayla diziyor. Şifreyi çözmek için hangi sıra izlenmelidir?', 'Önce sırayı ters çevir, sonra 3 geri kaydır', ['Önce 3 geri kaydır, sonra sırayı ters çevir', 'Önce 3 ileri kaydır, sonra sırayı ters çevir', 'Yalnız 3 geri kaydırmak yeterlidir'], 'Bileşke işlemlerin tersi ters sırada alınır: son yapılan işlem önce geri alınır.'),
  ('A = {1, 2} ve B = {3, 4} ise aşağıdaki kümelerden hangisi A\'dan B\'ye bir fonksiyondur?', '{(1, 4), (2, 4)}', ['{(1, 3), (1, 4)}', '{(1, 3)}', '{(3, 1), (4, 2)}'], 'Her A elemanı tam bir kez görünmelidir. (1, 4), (2, 4) bu koşulu sağlar; aynı görüntüye gitmeleri sorun değildir.'),
  ('Kendi tersine eşit olan bir f fonksiyonu için f(4) = 9 olduğu biliniyor. f(9) kaçtır?', '4', ['9', '1/9', 'Belirlenemez'], 'f = f⁻¹ ise f(4) = 9 bilgisi f⁻¹(9) = 4 demektir; f⁻¹ = f olduğundan f(9) = 4\'tür.'),
  ('Bir fiyat önce %50 artırılıp sonra 40 TL düşürülüyor. Bu işlem sonunda fiyatı değişmeyen ürünün fiyatı kaç TL\'dir?', '80', ['40', '60', '120'], '1,5x − 40 = x ise 0,5x = 40, x = 80 TL\'dir.'),
  ('Bir sinema salonunda bilet geliri satılan bilet sayısı n için G(n) = 80n TL\'dir ve salon 150 kişiliktir. G fonksiyonunun anlamlı tanım kümesi hangisidir?', '{0, 1, 2, ..., 150}', ['[0, 150] aralığındaki bütün gerçek sayılar', 'Bütün doğal sayılar', '{1, 2, ..., 12 000}'], 'Bilet sayısı tam sayı olmak zorundadır ve 0 ile salon kapasitesi 150 arasında kalır.'),
  ('Bir kişinin bir günde uyuduğu saat x olmak üzere uyanık kaldığı süre U(x) = 24 − x\'tir. U\'nun anlamlı tanım ve görüntü kümeleri hangisidir?', 'İkisi de [0, 24]', ['Tanım ℝ, görüntü ℝ', 'Tanım [0, 24], görüntü [24, 48]', 'Tanım (0, 24), görüntü ℝ⁺'], 'Uyku süresi 0 ile 24 saat arasındadır; uyanık süre de aynı aralıkta kalır.'),
  ('Bir f fonksiyonunun grafiği x < 2 için y = 1 yatay doğrusu, x ≥ 2 için ise y = x − 1 doğrusudur. f(0) + f(2) + f(4) toplamı kaçtır?', '5', ['4', '6', '7'], 'f(0) = 1, f(2) = 1, f(4) = 3\'tür. Toplam 5\'tir.'),
  ('f(x) fonksiyonu x < 0 için x², x ≥ 0 için −x kuralıyla tanımlanıyor. f\'nin görüntü kümesi hangisidir?', 'ℝ', ['[0, ∞)', '(−∞, 0]', 'ℝ − {0}'], 'Sol parça (0, ∞) değerlerini, sağ parça (−∞, 0] değerlerini alır. Birleşimleri bütün gerçek sayılardır.'),
  ('f fonksiyonu x < 1 için 2x, x ≥ 1 için x + 3 kuralına uyuyor. f\'nin grafiği x = 1\'de nasıldır?', 'Bir sıçrama vardır; sol taraf 2\'ye, sağ taraf 4\'e ulaşır', ['Grafik x = 1\'de hiç kopmadan, kesintisiz biçimde birleşerek devam eder', 'Düşey asimptot vardır', 'Grafik x = 1\'de tanımsızdır'], 'Sol parçanın x = 1\'e yaklaşırken değeri 2, sağ parçanın değeri 4\'tür. Değerler farklı olduğundan grafikte kopukluk oluşur.'),
  ('Bir parçalı fonksiyon x ≤ 3 için 6 − x, x > 3 için 2x − 3 biçimindedir. Fonksiyonun en küçük değeri kaçtır?', '3', ['0', '6', '−3'], 'Sol parça azalarak x = 3\'te 3\'e iner, sağ parça 3\'ten başlayıp artar. En küçük değer x = 3\'te alınan 3\'tür.'),
  ('f(x) = 5 − |x + 2| fonksiyonunun en büyük değeri ve bu değeri aldığı nokta hangisidir?', '5; x = −2', ['5; x = 2', '−2; x = 5', '7; x = 0'], '|x + 2| ≥ 0 olduğundan f ≤ 5\'tir; eşitlik x = −2\'de sağlanır.'),
  ('Paydası x² + 4 olan 1/(x² + 4) kesrinin x gerçek sayısı değiştikçe aldığı değerler hangi aralığı oluşturur?', '(0, 1/4]', ['[0, 1/4]', '(0, 4]', '[1/4, ∞)'], 'x² + 4 ≥ 4 olduğundan 0 < 1/(x² + 4) ≤ 1/4\'tür; üst sınır x = 0\'da alınır.'),
  ('2\'den √x çıkarılarak elde edilen 2 − √x ifadesi, x negatif olmayan sayılarda dolaşırken hangi değerleri alır?', '(−∞, 2]', ['[2, ∞)', '(−∞, 2)', '[0, 2]'], '√x ≥ 0 ve sınırsız büyüdüğünden 2 − √x en çok 2\'dir ve aşağı doğru sınırsızdır.'),
  ('f: {−2, −1, 0, 1, 2} → ℤ, f(x) = x² − x fonksiyonunun görüntü kümesinin eleman sayısı kaçtır?', '3', ['5', '4', '2'], 'f(−2) = 6, f(−1) = 2, f(0) = 0, f(1) = 0, f(2) = 2 olduğundan görüntü kümesi {0, 2, 6}\'dır ve 3 elemanlıdır.'),
  ('Bir parçalı fonksiyonun bir parçası x ≤ 2, diğeri x ≥ 2 için tanımlanmıştır ve iki kural x = 2\'de farklı sonuç veriyor. Bu durum için doğru yorum hangisidir?', 'Bu bir fonksiyon değildir; 2\'nin iki görüntüsü olur', ['Fonksiyon x = 2\'de sıfır değerini alır', 'Bu bir fonksiyondur; sınır noktasının hangi parçada olduğu önemsizdir', 'Fonksiyonun grafiği x = 2\'de düşey asimptot yapar'], 'x = 2 her iki parçaya da girer ve iki farklı çıktı alır; her girdinin tek çıktısı olma koşulu bozulur.'),
  ('f(x) = −x² + 6 fonksiyonu [−1, 2] aralığında tanımlanırsa en büyük ve en küçük değerleri nedir?', 'En büyük 6, en küçük 2', ['En büyük 5, en küçük 2', 'En büyük 6, en küçük 5', 'En büyük 7, en küçük 2'], 'Parabol x = 0\'da en yüksek değeri 6\'yı alır. Uçlarda f(−1) = 5, f(2) = 2 olduğundan en küçük değer 2\'dir.'),
  ('Bir f fonksiyonu x < 0 için −2x, 0 ≤ x < 3 için x², x ≥ 3 için 9 kuralına uyuyor. f(x) = 9 denkleminin çözüm kümesi nedir?', '{−4,5} ∪ [3, ∞)', ['{−4,5; 3}', '[3, ∞)', '{−3; 3}'], 'x < 0\'da −2x = 9 ise x = −4,5. 0 ≤ x < 3\'te x² = 9 çözümü (x = 3) bu parçada yoktur. x ≥ 3\'teki her değer 9 verir.'),
  ('Fırından çıkarılan bir kekin sıcaklığı zamanla oda sıcaklığına iner. Sıcaklık-zaman eğrisi için en uygun betimleme hangisidir?', 'Başta hızlı, sonra yavaşlayarak oda sıcaklığına yaklaşan azalan eğri', ['Sabit hızla sıfıra inen bir doğru', 'Önce azalan sonra artan bir eğri', 'Oda sıcaklığının altına inip orada kalan doğru'], 'Soğuma hızı sıcaklık farkıyla orantılıdır; fark küçüldükçe soğuma yavaşlar ve eğri oda sıcaklığına asimptotik olarak yaklaşır.'),
  ('Bir topu yukarı atan çocuğun gözlemine göre topun yerden yüksekliği zamana karşı nasıl bir eğri çizer?', 'Önce yükselip bir tepe yapan, sonra alçalan eğri', ['Sürekli yükselen bir doğru', 'Basamaklı bir çizgi', 'Önce alçalıp sonra yükselen eğri'], 'Top yavaşlayarak yükselir, en yüksek noktada bir an durur ve hızlanarak düşer; bu tepe yapan bir eğridir.'),
  ('Bir öğrencinin cep telefonu şarjı gün boyu kullanımla azalıyor, akşam prize takılınca artıyor. Şarj-zaman eğrisinin akşamki bölümü için hangisi doğrudur?', 'Eğim pozitiftir', ['Eğim negatiftir', 'Eğim sıfırdır', 'Eğri x eksenine paraleldir'], 'Şarj arttığı bölümde zaman ilerledikçe değer büyür; bu, pozitif eğim demektir.'),
  ('Bir şehrin aylık ortalama sıcaklığının yıl içindeki değişimi her yıl yaklaşık aynı biçimde tekrarlanıyor. Bu durumu en iyi hangi fonksiyon türü modeller?', 'Periyodik fonksiyon', ['Doğrusal fonksiyon', 'Üstel fonksiyon', 'Sabit fonksiyon'], 'Düzenli aralıklarla tekrarlanan değişimler periyodik fonksiyonlarla modellenir; burada periyot yaklaşık 12 aydır.'),
  ('Bir bankaya yatırılan para her ay sabit bir miktar eklenerek biriktiriliyor (faiz yok). Birikim-zaman grafiği aylık eklemeler anında yapılırsa nasıl görünür?', 'Her ay aynı yükseklikte yukarı sıçrayan basamaklar', ['Her ay giderek dikleşen, hiç kesintisi olmayan pürüzsüz bir eğri', 'Her ay aşağı inen basamaklar', 'Yatay bir doğru'], 'Para yalnız ekleme anlarında artar, aralarda sabit kalır; ekleme miktarı aynı olduğundan basamaklar eşit yüksekliktedir.'),
  ('Uçağın kalkıştan inişe kadarki yüksekliği zamana göre çizildiğinde ortadaki uzun yatay bölüm neyi gösterir?', 'Seyir irtifasında sabit yükseklikte uçuşu', ['Uçağın yerde beklemesini', 'Uçağın hızının sıfır olduğunu ve havada asılı kaldığını', 'Uçağın sürekli alçalmasını'], 'Yükseklik-zaman eğrisinde yatay bölüm yüksekliğin değişmediğini gösterir; bu, uçağın durduğu anlamına gelmez.'),
  ('Bir taksi ücretinin gidilen mesafeye göre değişimi \'açılış ücreti + kilometre başı sabit ücret\' biçimindeyse ücret-mesafe grafiği nasıl başlar?', 'y eksenini açılış ücreti kadar yukarıda keser', ['Orijinden başlar', 'x eksenini açılış ücretine eşit uzaklıktaki noktada keser', 'y eksenini kesmez'], 'Mesafe 0 iken ücret açılış ücretine eşittir; doğru y eksenini bu değerde keser.'),
  ('Bir ağaç her yıl yaklaşık aynı miktarda boy atıyor. Boy-yaş grafiği hangi fonksiyon türüne yakındır?', 'Doğrusal', ['Üstel', 'Periyodik', 'Ters orantılı'], 'Eşit sürelerde eşit artış sabit eğimli bir doğru verir.'),
  ('Bir okulun bahçesindeki gölgenin uzunluğu sabahtan öğlene kısalıp öğleden akşama uzuyor. Gölge uzunluğu-saat grafiğinin en alçak noktası yaklaşık ne zamana karşılık gelir?', 'Güneşin en yüksekte olduğu öğle saatine', ['Sabah güneşin ufukta doğmaya başladığı ilk ana', 'Akşam güneşin battığı ana', 'Gece yarısına'], 'Güneş en yüksekteyken ışınlar en dik gelir ve gölge en kısadır.'),
  ('Bir merdivenden çıkan kişinin yerden yüksekliği basamak sayısına göre çizilirse nasıl bir grafik oluşur?', 'Eşit aralıklı noktalar dizisi', ['Kesintisiz, yukarı açılan ve tepesi yerde olan bir parabol', 'Yatay bir doğru', 'Azalan bir eğri'], 'Basamak sayısı tam sayıdır ve her basamak aynı yüksekliği ekler; grafik bir doğru üzerinde eşit aralıklı noktalardan oluşur.'),
  ('Bir silindir biçimli su deposunun dibindeki musluk açıldığında su seviyesi başta hızlı, sonra yavaş düşüyor. Seviye-zaman eğrisi nasıldır?', 'Gittikçe yataylaşan azalan eğri', ['Gittikçe dikleşen azalan eğri', 'Sabit eğimli azalan doğru', 'Artan bir eğri'], 'Akış hızı su yüksekliğine bağlıdır; seviye düştükçe akış yavaşlar ve eğri yataylaşarak iner.'),
  ('f fonksiyonunun en büyük değeri 8\'dir ve bu değer x = 3\'te alınır. g(x) = f(x + 1) − 5 fonksiyonunun en büyük değeri ve alındığı nokta hangisidir?', '3; x = 2', ['3; x = 4', '8; x = 2', '13; x = 4'], 'Yatay öteleme apsisi 1 sola kaydırır (x = 2), düşey öteleme değeri 5 azaltır (8 − 5 = 3).'),
  ('f\'nin grafiği x = 4 doğrusuna göre simetriktir. g(x) = f(x − 2) fonksiyonunun grafiği hangi doğruya göre simetriktir?', 'x = 6', ['x = 2', 'x = 4', 'x = 8'], 'Grafik 2 birim sağa kayınca simetri ekseni de 2 birim sağa kayar: 4 + 2 = 6.'),
  ('f\'nin sıfırları −4, 0 ve 6\'dır. h(x) = f(−x) fonksiyonunun sıfırlarının toplamı kaçtır?', '−2', ['2', '0', '−10'], '−x = −4, 0, 6 için x = 4, 0, −6 olur. Toplam −2\'dir.'),
  ('f\'nin tanım kümesi [−2, 4], görüntü kümesi [1, 3]\'tür. g(x) = f(x) + 2 fonksiyonunun tanım ve görüntü kümeleri hangisidir?', 'Tanım [−2, 4], görüntü [3, 5]', ['Tanım [0, 6], görüntü [1, 3]', 'Tanım [0, 6], görüntü [3, 5]', 'Tanım [−2, 4], görüntü [1, 3]'], 'Düşey öteleme yalnız çıktıları değiştirir; tanım kümesi aynı kalır, görüntü kümesi 2 birim yukarı kayar.'),
  ('f\'nin grafiği y eksenini (0, 5) noktasında kesiyor. g(x) = 2f(x) − 3 grafiği y eksenini hangi noktada keser?', '(0, 7)', ['(0, 10)', '(0, 2)', '(0, 13)'], 'g(0) = 2·5 − 3 = 7\'dir.'),
  ('f\'nin yatay asimptotu y = 2\'dir. g(x) = f(x) − 2 fonksiyonunun yatay asimptotu hangisidir?', 'y = 0', ['y = 2', 'y = −2', 'y = 4'], 'Düşey öteleme asimptotu da aynı ölçüde kaydırır: 2 − 2 = 0.'),
  ('f\'nin eğrisi yatay ekseni yalnız x = −1 ve x = 5\'te kesiyor. Çıktıları 4 ile çarpılan y = 4f(x) eğrisi yatay ekseni nerelerde keser?', '(−1, 0) ve (5, 0)', ['(−4, 0) ve (20, 0)', '(−1/4, 0) ve (5/4, 0)', '(3, 0) ve (9, 0)'], 'Düşey uzatma sıfır olan ordinatları değiştirmez; kesişim noktaları aynı kalır.'),
  ('Tek bir f fonksiyonu için g(x) = f(x − 1) + 3 fonksiyonunun grafiği hangi noktaya göre simetriktir?', '(1, 3)', ['(−1, 3)', '(3, 1)', '(0, 0)'], 'Tek fonksiyon orijine göre simetriktir; 1 sağa ve 3 yukarı öteleme simetri merkezini (1, 3)\'e taşır.'),
  ('Bir f fonksiyonunun [0, 10] aralığındaki ortalama değişim hızı 3\'tür. g(x) = f(x) + 7 fonksiyonunun aynı aralıktaki ortalama değişim hızı kaçtır?', '3', ['10', '21', '7'], 'Düşey öteleme iki uçtaki değerleri aynı miktarda artırır; fark ve dolayısıyla ortalama değişim hızı değişmez.'),
  ('f(x) = x² − 4 için y = f(|x|) ile y = |f(x)| fonksiyonlarından hangisi farklı bir grafiğe sahiptir?', 'Yalnız |f(x)| farklıdır; f(|x|) = f(x)\'tir', ['Yalnız f(|x|) farklıdır', 'İkisi de f\'den farklıdır', 'İkisi de f\'ye eşittir'], 'f çift olduğundan f(|x|) = f(x)\'tir. f\'nin (−2, 2) aralığında negatif olan bölümü |f(x)|\'te yukarı katlanır.'),
  ('Birbirinin çarpmaya göre tersi olan 2ˣ ve 2^(−x) terimlerinin toplamı en az kaç olabilir?', '2', ['1', '0', '4'], 'İki pozitif sayı a ve 1/a için a + 1/a ≥ 2\'dir; eşitlik 2ˣ = 1, yani x = 0\'da sağlanır.'),
  ('Bir sosyal medya paylaşımını gören kişi sayısı her saat 3 katına çıkıyor. İlk saat sonunda 40 kişi gördüyse 4. saatin sonunda kaç kişi görmüştür?', '1 080', ['480', '360', '3 240'], '1. saat 40, 2. saat 120, 3. saat 360, 4. saat 1 080\'dir; üç katlama yapılmıştır.'),
  ('Hangi formül her yıl %8 değer kaybeden bir makinenin t yıl sonraki değerini doğru verir (başlangıç değeri D₀)?', 'D₀·0,92ᵗ', ['D₀·1,08ᵗ', 'D₀ − 0,08t', 'D₀·0,08ᵗ'], 'Her yıl kalan değer %92\'dir; t yıl sonra D₀ çarpı 0,92ᵗ olur.'),
  ('Bir öğrencinin her dersten aldığı notu gösteren eşleme (ders → not) için hangisi kesinlikle doğrudur?', 'Her derse tek bir not karşılık geliyorsa fonksiyondur', ['Notlar farklı değilse fonksiyon değildir', 'Ters eşleme (not → ders) de her durumda bir fonksiyon belirtir', 'Ders sayısı not sayısına eşit olmalıdır'], 'Aynı notu alan dersler olabilir; bu fonksiyon olmayı engellemez ama tersin fonksiyon olmasını engeller.'),
  ('f(x) = (x − 1)(x + 3) fonksiyonunun hangi aralıkta negatif olduğu, iki çarpanın işaretleri düşünülerek bulunursa hangisi elde edilir?', '(−3, 1)', ['(−∞, −3)', '(1, ∞)', '(−∞, −3) ∪'], '−3 < x < 1\'de x − 1 negatif, x + 3 pozitiftir; çarpım negatiftir. Dışında iki çarpan aynı işaretlidir.'),
  ('[0, ∞) aralığında tanımlı f(x) = √(x) + 3 fonksiyonunun tersinin tanım kümesi hangisidir?', '[3, ∞)', ['[0, ∞)', '(3, ∞)', '[−3, ∞)'], 'f\'nin görüntü kümesi [3, ∞)\'dur; tersin tanım kümesi bu kümedir.'),
  ('f(x) = |x − 3| fonksiyonunun birebir olması için tanım kümesi aşağıdakilerden hangisi seçilebilir?', '[3, ∞)', ['[0, ∞)', '[−3, 3]', 'ℝ'], 'V grafiğinin tepesi x = 3\'tedir; tepenin bir yanındaki kol birebirdir. [0, ∞) seçilirse 2 ve 4 aynı değeri alır.'),
  ('Tam kısım fonksiyonu için ⌊x⌋ = 2x − 3 eşitliğini sağlayan bütün x gerçek sayılarının toplamı kaçtır?', '5,5', ['5', '2,5', '6'], '⌊x⌋ = n ise x = (n + 3)/2 olmalı ve n ≤ x < n + 1 sağlanmalıdır; bu 1 < n ≤ 3 verir. n = 2 için x = 2,5, n = 3 için x = 3 bulunur. Toplam 5,5\'tir.'),
  ('Bir ilacın kandaki derişimi C(t) = 10t/(t² + 1) mg/L ile modelleniyor (t saat). İlaç alındığı anda (t = 0) derişim kaçtır?', '0', ['10', '1', '5'], 'C(0) = 0/1 = 0\'dır; ilaç başta kana geçmemiştir.'),
  ('Bir işçinin öğrenme modelinde günde üretilen parça sayısı P(d) = 60d/(d + 4) (d: çalışılan gün). Kaçıncı günde günlük üretim 40 parçaya ulaşır?', '8', ['6', '10', '4'], '60d/(d + 4) = 40 ise 60d = 40d + 160, d = 8\'dir.'),
  ('Bir mobil pakette ayda 10 GB\'a kadar 150 TL ödeniyor; aşılan her GB için 20 TL ekleniyor. 14,5 GB kullanan bir abone (kesirli GB\'lar tam sayılmak üzere) kaç TL öder?', '250', ['240', '290', '230'], 'Aşım 4,5 GB\'tır; kesir tam sayıldığından 5 GB ücretlendirilir: 150 + 5·20 = 250 TL.'),
  ('Aşağıdaki fonksiyonlardan hangisi kendi en geniş tanım kümesinde yatay doğru testini geçer?', 'y = √x', ['y = x²', 'y = |x|', 'y = x⁴ − 1'], '√x kesin artandır; her yatay doğru grafiği en çok bir kez keser. Diğerleri çift fonksiyondur ve testi geçemez.'),
  ('Bir f fonksiyonu için f(−2) = 3 ve f(4) = −1 veriliyor. Bu bilgilere göre grafiğin kesinlikle geçtiği noktalar hangileridir?', '(−2, 3) ve (4, −1)', ['(3, −2) ve (−1, 4)', '(−2, −1) ve (4, 3) noktaları', '(2, 3) ve (−4, −1)'], 'f(a) = b bilgisi grafiğin (a, b) noktasından geçtiğini gösterir.'),
  ('Bir doğrusal fonksiyonun grafiği (2, 9) noktasından geçiyor ve x 1 arttıkça y 4 azalıyor. Grafiğin y eksenini kestiği nokta hangisidir?', '(0, 17)', ['(0, 1)', '(0, 9)', '(0, 13)'], 'x 2 azalınca y 8 artar: 9 + 8 = 17. Kural y = −4x + 17\'dir.'),
  ('t² − 2t kuralına sahip g için 3 ve −1 girdilerinin çıktıları arasındaki g(3) − g(−1) farkı kaçtır?', '0', ['6', '−6', '4'], 'g(3) = 9 − 6 = 3, g(−1) = 1 + 2 = 3\'tür. Fark 0 olur; iki nokta tepe x = 1\'e eşit uzaklıktadır.'),
  ('f(x) = 2x + 3 olmak üzere f(x) = f(2) + f(x − 2) eşitliği hangi x değerleri için doğrudur?', 'Hiçbir x için', ['Her x için', 'Yalnız x = 2 için', 'Yalnız x = 0 için'], 'Sağ taraf 7 + 2x − 1 = 2x + 6, sol taraf 2x + 3\'tür; eşitlik 3 = 6 çelişkisine varır.'),
  ('Kare ile mutlak değerin toplamından oluşan x² + |x| kuralı simetri bakımından nasıl sınıflandırılır?', 'Çifttir', ['Tektir', 'Ne tek ne çifttir', 'Hem tek hem çifttir'], '(−x)² + |−x| = x² + |x| olduğundan f(−x) = f(x)\'tir.'),
  ('Bir saatin yelkovanının ucunun 12 rakamından olan uzaklığı zamanın periyodik bir fonksiyonudur. Bu fonksiyonun periyodu kaç dakikadır?', '60', ['12', '30', '720'], 'Yelkovan her 60 dakikada bir tam tur atar ve aynı konuma döner.'),
  ('f fonksiyonu [−3, 3] aralığında tanımlı ve çifttir; [0, 3]\'te 0\'dan 6\'ya kesin artandır. f\'nin en küçük değeri ve alındığı nokta hangisidir?', '0; x = 0', ['−6; x = −3', '6; x = 3', '0; x = −3'], 'Sağ yarıda en küçük değer f(0) = 0\'dır. Sol yarı simetrik olduğundan da 0\'ın altına inilmez.'),
  ('Bir otomobil kiralama firmasında ücret gün sayısının fonksiyonudur: Ü(g) = 600g + 200. Ü⁻¹ fonksiyonunun girdisi ve çıktısı nedir?', 'Girdisi ücret, çıktısı gün sayısı', ['Girdisi gün sayısı, çıktısı ücret', 'Girdisi ve çıktısı ücrettir', 'Girdisi günlük ücret, çıktısı toplam ücret'], 'Ters fonksiyon asıl fonksiyonun çıktısını girdi olarak alır ve karşılık gelen girdiyi verir.'),
  ('Ü(g) = 600g + 200 kiralama ücretine göre 3 800 TL ödeyen bir müşteri kaç gün araç kiralamıştır?', '6', ['7', '5', '6,5'], '600g + 200 = 3 800 ise 600g = 3 600, g = 6 gündür; bu Ü⁻¹(3 800) değeridir.'),
  ('f fonksiyonunun grafiği tamamen birinci bölgededir. y = −f(−x) grafiği hangi bölgede yer alır?', 'Üçüncü bölgede', ['İkinci bölgede', 'Dördüncü bölgede', 'Birinci bölgede'], 'Orijine göre yansıma (x, y) noktasını (−x, −y)\'ye götürür; birinci bölge üçüncü bölgeye gider.'),
  ('Eğrisi bütünüyle birinci bölgede bulunan bir f, dikey eksene göre aynalanırsa (y = f(−x)) yeni eğri hangi bölgeye düşer?', 'İkinci bölgede', ['Üçüncü bölgede', 'Dördüncü bölgede', 'Birinci bölgede'], 'y eksenine göre yansıma apsisin işaretini değiştirir; x > 0, y > 0 olan noktalar x < 0, y > 0 bölgesine geçer.'),
  ('\'Tanım kümesi bütün gerçek sayılar, grafiği x eksenine paralel bir doğru\' olan fonksiyon için hangi kural uygundur?', 'y = −4', ['y = −4x', 'x = −4', 'y = x − 4'], 'x eksenine paralel doğru y = c biçimindedir; bu sabit fonksiyondur. x = −4 ise düşey doğrudur ve fonksiyon değildir.'),
  ('Bir küpün kenar uzunluğu, hacim V\'nin fonksiyonu olarak a(V) = ∛V ile verilir. Hacim 8 katına çıkarsa kenar kaç katına çıkar?', '2', ['8', '4', '√8'], '∛(8V) = 2∛V olduğundan kenar 2 katına çıkar.'),
  ('Bir otobüs firması 6 yaşından küçük çocuklardan ücret almıyor; bilet fiyatını yaş y için tam yıl olarak hesaplıyor. 5 yıl 11 aylık bir çocuğun ⌊yaş⌋ değeri kaçtır ve ücret ödenir mi?', '5; ödenmez', ['6; ödenir', '5; ödenir', '6; ödenmez'], '5 yıl 11 ay ≈ 5,92 yıldır; ⌊5,92⌋ = 5 ve bu 6\'dan küçük olduğundan ücret alınmaz.'),
  ('Bir kâğıt her katlanışta kalınlığı iki katına çıkıyor. 0,1 mm kalınlığındaki kâğıt 5 kez katlanırsa kalınlık kaç mm olur?', '3,2', ['1', '0,5', '1,6'], '0,1·2⁵ = 0,1·32 = 3,2 mm\'dir.'),
];
